    [3823] = "Mate 15 Ogros-magos Pirobucho, 7 Ogros Pirobucho e 7 Brutamontes Ogros Pirobucho e fale novamente com Oralius quando terminar.",
    [3824] = "Encontre Gor'tesh em algum lugar a oeste do Rochedo Malhorrendo. Mate Gor'tesh e depois leve a Cabeça Decepada do Gor'tesh de volta a Oralius nas Estepes Ardentes.",
    [3825] = "Pegue a Cabeça Decepada do Gor'Tesh e coloque no topo do Rochedo Malhorrendo. Procure um montinho de terra macia para espetar a estaca.",
    [3841] = "Fale com Quentin em Mil Agulhas.",
    [3842] = "Entregue 2 Elixires de Fortitude para Quentin em Mil Agulhas.",
    [3843] = "Leve o Ovo Frágil de Dardejante às Terras Agrestes e fale com Agnar Domaferas, mas corra, você só tem uma hora para encontrá-lo antes que o filhote dentro do ovo morra.",
    [3844] = "Olhe em volta da lagoa para descobrir uma pista sobre quem pode ser o dono do bote destruído.",
    [3845] = "Examine os itens dentro da bolsa e leve até o dono.",
    [3861] = "Procure a Ração Especial de Galinha e volte até sua nova amiga galinácea. Em seguida, use a expressão /incentivar diante dela e lhe dê a Ração Especial de Galinha.",
    [3881] = "Leve um Caixote de Comestíveis e o Equipamento de Pesquisa para Williden Marshal in Cratera Un'Goro.",
    [3882] = "Leve 8 Ossos de Dinossauro para Chispa Minanilo na Cratera Un'Goro.",
    [3883] = "Use a Ampola de Amostra para coletar uma Amostra de Parede de Colmeia de uma das incubadoras Gorishi na Cratera Un'Goro. Procure as câmaras com larvas. Leve a Amostra de Parede de Colmeia para Hol'anyee Marshal na Cratera Un'Goro.",
    [3884] = "Devolva o diário a Williden Marshal na Cratera Un'Goro.",
    [3901] = "Mate 12 Esqueletos Range-ossos e fale novamente com o Sacerdote Sombrio Sarvis em Plangemortis quando terminar.",
    [3902] = "Procure 6 peças de Material Reaproveitado nas redondezas de Plangemortis e fale novamente com o Necroguarda Saulo.",
    [3903] = "Fale com Madel Quintana.",
    [3904] = "Leve 8 caixotes da Colheita da Madel para Madel Quintana na Abadia de Vila Norte.",
    [3905] = "Leve o Manifesto da Uva para o Irmão Neals na Abadia de Vila Norte.",
    [3906] = "Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa.",
    [3907] = "Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante.",
    [3908] = "Leve a Espada de Linken para Bruna Covaneve em Hibérnia.",
    [3909] = "Procure Gregan Cospechope ao norte de Feralas. Descubra com ele como obter o elixir Videre, depois fale novamente com Bruna Covaneve em Hibérnia.",
    [3912] = "Vá até o cemitério perto de Geringontzan e use o Elixir Videre. Siga as outras instruções de Bruna para achar Gaeriyan.",
    [3913] = "Ressuscite, depois procure a lápida que Gaeriyan disse para você encontrar.",
    [3914] = "Leve a Espada Superior de Linken para Linken na Cratera Un'Goro.",
    [3921] = "Leve a Rebimboca Quebrada para Juntatudy Jogafora.",
    [3922] = "Leve 15 Chumbalheiras para Juntatudy Jogafora nos Sertões.",
    [3923] = "Leve a Rebimboca Quebrada e Surrada para o Rilli Passomal em Orgrimmar.",
    [3924] = "Leve o Manual da Rebimboca para Rilli Passomal em Orgrimmar.",
    [3941] = "Encontre J.D. Neri na caverna do Refúgio do Marshal.",
    [3942] = "Encontre Eridan Brisazul no sul da Selva Maleva.",
    [3961] = "Leve o Totem de Prata de Aquementas para Linken no Refúgio do Marshal.",
    [3962] = "Vá para o Pico Penacho de Fogo, ao sul do Refúgio do Marshal. Encontre Agni e use o totem para remover sua aura de proteção. Uma vez que for derrotado, pegue a Chama Dourada na caverna.",
    [3981] = "Encontre o Comandante Gor'shak no Abismo Rocha Negra. Você se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão.",
    [3982] = "Defenda Gor'shak.",
    [4001] = "Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar. Gor'shak mencionou que Kharan estava preso em uma cela próxima.",
    [4002] = "Fale com Thrall se estiver <preparado/preparada> para assumir a missão que ele planejou.",
    [4003] = "Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno.",
    [4004] = "Fale novamente com Thrall!",
    [4005] = "Leve o Livro de Aquor, as Garras Prateadas e o Coração de Ferrárbol até Tanaris. Use o Livro de Aquor para evocar Aquementas. Após ter completado o totem, leve-o para J.D. Neri no Refúgio do Marshal.",
    [4021] = "Leve um Pedaço do Estandarte de Krom'zar para Regthar Portões-da-morte, a oeste da Encruzilhada.",
    [4022] = "Mostre a Ciro Terepento a Muda de Pele da Revoada Negra que você recebeu de Velarok Lamicélere.",
    [4023] = "Mostre a Ciro Terepento uma prova de seu valor. Você tem a impressão de que Ciro já sabe que você não é digna.",
    [4024] = "Vá para o Abismo Rocha Negra e mate Bael'gar. A única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora. Leve a Essência Abrasadora Aprisionada para Ciro Terepento.",
    [4061] = "Vá para as Estepes Ardentes e recupere 10 Estilhaços Elementais Fraturados para a Hierofante Theodora Malvadania. Você se lembra que Theodora mencionou que os golens e elementais dessa região são uma fonte desses estilhaços.",
    [4062] = "Leve a Amostra de Estilhaço Elemental para Lotwil Viriato. Segundo Theodora, Lotwil estava escalado em um acampamento ao leste.",
    [4063] = "Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal.",
    [4081] = "Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado.",
    [4082] = "Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído.",
    [4084] = "Colete 11 Garras Prateadas e 1 Coração de Ferrárbol para Eridan Brisazul na Selva Maleva.",
    [4101] = "Leve 15 Âmbares de Sangue para Arathandris Argencélio na Selva Maleva.",
    [4102] = "Leve 15 Âmbares de Sangue para Maibess Brisa do Rio em Selva Maleva.",
    [4120] = "Talo Casco de Espinhos da Aldeia Mojache em Feralas quer que você mate 12 Ursos-cinzentos Garraivoso e 12 Assoladores Patavil em Selva Maleva.",
    [4121] = "Escolte seu prisioneiro, Grark Lorkrub, pelas Estepes Ardentes, atravessando a Montanha Rocha Negra até chegar à Garganta Abrasadora. Você se lembra de ter ouvido Lexlort dizer que mandaria seus homens esperar no outro lado para levar Grark sob custódia. Você também vai precisar entregar os Grilhões de Tório para Lexlort.",
    [4122] = "Vá para as Estepes Ardentes e encontre Grark Lorkrub. Segundo Lexlort, ele foi visto pela última vez em uma imensa fortaleza Rocha Negra. Quando encontrar Grark Lorkrub, use os Grilhões de Tório para prendê-lo e levá-lo de volta à Garganta Abrasadora, passando pela Montanha Rocha Negra. Os homens de Lexlort estarão esperando do outro lado para levar Grark sob sua custódia.",
    [4123] = "Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes.",
    [4124] = "Fale com Ginro Laracendis no Domínio de Plumaluna.",
    [4125] = "Encontre o barco do mensageiro em algum lugar da costa de Feralas.",
    [4126] = "Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos.",
    [4127] = "Volte ao Domínio de Plumaluna e mostre a Faca Descartada que você achou a Ginro Laracendis.",
    [4128] = "Fale com Ragnar Cervaforte.",
    [4129] = "Leve a Faca Descartada para Quintis Jonespyre no Domínio de Plumaluna.",
    [4130] = "Fale com Ginro Laracendis no Domínio de Plumaluna.",
    [4131] = "Procure os acampamentos dos Gnolls Patábua ao sul de Feralas para obter pistas dos pertences do mensageiro ou dele próprio.",
    [4132] = "Viaje para o Abismo Rocha Negra e mate o General Forjaversa! Fale novamente com o Senhor da Guerra Trincador quando a tarefa estiver concluída.",
    [4133] = "Fale com a Mestra Sombria Vivian Latumba em Karrath.",
    [4134] = "Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath.",
    [4135] = "Agora que o último paradeiro conhecido de Patiphe foi descoberto, continue sua busca por ele ou seus restos na Profundeza Atormentada. De acordo com o bilhete, ela fica ao sul dos acampamentos dos gnolls Patábua.",
    [4136] = "Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes.",
    [4141] = "Colha 15 Pétalas Sangrentas e fale novamente com Melco.",
    [4142] = "Leve uma Pétala Sangrenta para Gregan Cospechope em Feralas.",
    [4143] = "Colha 5 amostras de Bruma de Atal'ai, depois fale novamente com Melco na Cratera Un'Goro.",
    [4145] = "Cace 5 Açoitadeiras Pétala Sangrenta, 5 Látegas Pétala Sangrenta, 5 Esfoladoras Pétala Sangrenta e 5 Laçadoras Pétala Sangrenta para Lário, do Refúgio do Marshal.",
    [4146] = "Entregue a Fulminadora Descarregada e 5 amostras de Bruma de Atal'ai a Lário, no Refúgio do Marshal.",
    [4147] = "Vá até a oficina de Marlon Catarrebite na Vila Catraca.",
    [4161] = "Colete 7 Pernas Pequenas de Aranha para Zarrin, de Dolanaar.",
    [4181] = "Se quiser aprender mais sobre a Engenharia Goblínica, leve o Manual das Disciplinas de Engenharia até Nixx Molapinhão, em Geringontzan.",
    [4182] = "Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída.",
    [4183] = "Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão.",
    [4184] = "Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon. Bolvar reside na Bastilha Ventobravo.",
    [4185] = "Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor.",
    [4186] = "Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida.",
    [4201] = "Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra.",
    [4223] = "Fale com o Oficial Maxwell nas Estepes Ardentes.",
    [4224] = "Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa. Você se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte.",
    [4241] = "Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas. Você se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão.",
    [4242] = "Leve as más notícias ao Oficial Maxwell.",
    [4243] = "Encontre A-Me 01 na Cratera Un'Goro.",
    [4244] = "Encontre uma Carcaça de Mithril e leve A-Me 01 de volta para a Cratera Un'Goro.",
    [4245] = "Escolte A-Me 01 de volta para Karna Trilheiro na Cratera Un'Goro.",
    [4261] = "Escolte Arei para um lugar seguro, depois fale com Kainet Brisacalma em Cantilenda, que fica no lado leste do Vale Gris.",
    [4262] = "Mate o Mestre Supremo Piro e fale novamente com Jalinda Ramo. Você se lembra de Jalinda ter dito que Piro guarda a pedreira. Que tal procurar por lá?",
    [4263] = "Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!",
    [4264] = "Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal.",
    [4265] = "Liberte Patiphe da colmeia de Zukk'ash. Avise a Ginro Laracendis no Domínio de Plumaluna que Patiphe está são e salvo.",
    [4266] = "Fale com Shandris Plumaluna no Domínio de Plumaluna.",
    [4267] = "Leve o Relatório do Patiphe para Gracinha Forçânima em Darnassus.",
    [4281] = "Leve o Pacote Extraviado para Falfindel Trilhemas em Thalanaar.",
    [4282] = "Recupere as Informações Perdidas do Marechal Vilasboas. O Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa.",
    [4283] = "Oralius quer 50 Medalhões Rocha Negra. Há grandes chances de esses medalhões serem encontrados com orcs nas Estepes Ardentes.",
    [4284] = "Colete 7 Cristais de Poder de cada uma das seguintes cores: vermelho, azul, amarelo e verde. Leve-os para J.D. Neri no Refúgio do Marshal.",
    [4285] = "Descubra a localização da Torre de Cristal Norte, que fica na Cratera Un'Goro.",
    [4286] = "Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\".",
    [4287] = "Descubra a localização da Torre de Cristal Leste, que fica na Cratera Un'Goro.",
    [4288] = "Descubra a localização da Torre de Cristal Oeste, que fica na Cratera Un'Goro.",
    [4289] = "Leve 2 Pelagens de Gorila de Un'Goro, 2 Pelagens de Pisoteador de Un'Goro, 2 Pelagens de Trovejador de Un'Goro para Torwa Mateiro na entrada da Cratera Un'Goro.",
    [4290] = "Encontre a carcaça mais recente de uma presa morta por Lar'korwi e roube um Pedaço de Carcaça de Manguadonte. Depois disso, fale novamente com Torwa Mateiro na Cratera Un'Goro.",
    [4291] = "Leve 2 Glândulas de Feromônio de Ravassauro para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.",
    [4292] = "Use o conteúdo do Bornal do Torwa para evocar Lar'korwi e derrotá-lo. Então, leve a Cabeça do Lar'korwi para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.",
    [4293] = "Colha Amostras de Visgo da Selva Maleva de qualquer visgo em Selva Maleva. Depois, usando o Equipamento de Teste ao lado do Químico Sérgio, na Cidade Baixa, veja quais das suas amostras são as mais corrompidas. Leve 5 das Amostras Corrompidas da Selva Maleva que você encontrar para o Químico Sérgio.",
    [4294] = "Colha Amostras de Visgo de Un'Goro de qualquer visgo na Cratera Un'Goro. Depois, usando o Equipamento de Teste ao lado do Químico Sérgio, na Cidade Baixa, veja quais das suas amostras são as mais puras. Leve 5 das Amostras Puras de Un'Goro que você encontrar para o Químico Sérgio.",
    [4296] = "Leve a Transcrição de Tabuleta para Maxwort Uberraio nas Estepes Ardentes.",
    [4297] = "Leve 5 Lombos de Espreitador Jubaprata para Agnar Domaferas nas Terras Agrestes.",
    [4298] = "Fale com Agnar Domaferas nas Terras Agrestes.",
    [4300] = "Leve 8 Garras Brancas de Ravassauro para Sona'rima em Orgrimmar.",
    [4301] = "Leve Pelagem de U'cha para Torwa Mateiro na entrada da Cratera Un'Goro.",
    [4321] = "Fale com J.D. Neri em um instante.",
    [4322] = "Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell.",
    [4324] = "Fale com Yuka Parafuseta nas Estepes Ardentes.",
    [4341] = "Viaje para Abismo Rocha Negra e encontre Kharan Feromalho. O Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão.",
    [4342] = "Ouça Kharan Feromalho contar a história dele.",
    [4361] = "Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze.",
    [4362] = "Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan.",
    [4363] = "Volte a Altaforja e fale com o Rei Magni Barbabronze.",
    [4402] = "Leve 10 Sabras para Galgar. Você lembra que ele disse que se encontram sabras perto dos cactos.",
    [4421] = "Mate 11 Devotos Vis Flamejade, 9 Assombrantes Flamejade, 9 Desgarrados Flamejade e Xavathras. Fale novamente com Eridan Brisazul na Selva Maleva quando a tarefa estiver completa.",
    [4441] = "Viaje para Darnassus e use a Ampola de Eridan para coletar uma Ampola de Água Benta no Templo da Lua. Fale novamente com Eridan, levando a ampola cheia.",
    [4442] = "Fale novamente com Eridan em alguns instantes.",
    [4449] = "Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora.",
    [4450] = "Pegue a cópia do Livro-Caixa de Rugov A. Massoaço e encontre os itens listados antes de ir falar com ele em Tanaris.",
    [4451] = "Encontre a Garganta Abrasadora e descubra para que serve a Chave da Casinha de Pedrassuja que você encontrou.",
    [4485] = "Fale com Benedito Brião em Ventobravo.",
    [4486] = "Fale com Benedito Brião em Ventobravo.",
    [4487] = "Fale com Strahad Farsan na Vila Catraca.",
    [4488] = "Fale com Strahad Farsan na Vila Catraca.",
    [4489] = "Fale com Strahad Farsan na Vila Catraca.",
    [4490] = "Fale com Strahad Farsan, na Vila Catraca, para aprender a habilidade de evocar um Corcel Vil.",
    [4491] = "Leve Ringo até Espraga Froque, no Refúgio do Marshal. Se Ringo desmaiar, use o Cantil da Espraga para reanimá-lo.",
    [4492] = "Encontre Ringo no Pico Penacho de Fogo.",
    [4493] = "Fale com o Alquimista Almofarrista em Geringontzan.",
    [4494] = "Fale com o Alquimista Almofarrista em Geringontzan.",
    [4495] = "Encontre Iverron perto da caverna ao norte.",
    [4496] = "Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.",
    [4501] = "Mate 10 Pterrordaxes e 15 Pterrordaxes Frenéticos, então fale com Espraga Froque no Refúgio do Marshal.",
    [4502] = "Colete 9 amostras das Cinzas de Un'Goro dos elementais de fogo ao redor do vulcão da Cratera Un'Goro, e leve-as para Fanny Quito, em Vila Catraca.",
    [4503] = "Colete 8 Escamas de Dimetrodonte Palmado e 8 Escamas de Pterrordax Palmado para Chislo no Refúgio do Marshal.",
    [4504] = "Colete 12 amostras de Piche Supergrudento para Tran'rek em Geringontzan.",
    [4505] = "Colete uma amostra de água corrompida do poço lunar dos Sátiros Flamejade e leve-a para Winna Perícon no Posto Peçonha.",
    [4506] = "Leve o gatinho de Winna para o poço lunar corrompido, solte-o e depois o leve de volta para Winna. Quando retornar, clique no gato para deixá-lo com Winna.",
    [4507] = "Derrote a Rainha da Colmeia Gorishi assim que ela for atraída. Leve o Cérebro da Rainha Gorishi para o Alquimista Almofarrista em Geringontzan.",
    [4508] = "Leve o Relatório de Un'Goro do Almofarrista para Gracinha Forçânima em Darnassus.",
    [4509] = "Leve o Relatório de Un'Goro do Almofarrista para Zilzibin Tamborleiro em Orgrimmar.",
    [4510] = "Leve o Comprovante Bancário a Idriana no banco de Darnassus.",
    [4511] = "Leve o Comprovante Bancário para Karus, no banco de Orgrimmar.",
    [4512] = "Entregue 6 Jarras de Gosma Amaldiçoada Cheias e 6 Jarras de Gosma Maculada Cheias para Laris Vagarroda em Altaforja.",
    [4513] = "Leve 10 Jarras Cheias de Amostra Pura para Laris Vagarroda em Altaforja. Caso você não consiga encontrar as gosmas puras, peça mais pistas para o Laris.",
    [4521] = "Trull Ruinazar em Selva Maleva quer que você mate 15 Ferujas Furiosas e 15 Ferujas Maltrapilhas.",
