    [4581] = "Leve o Bilhete de Shindrell para Kainet Brisacalma em Cantilenda.",
    [4621] = "Mate o Mestre de Frota Chifre do Mar e o Barão Rezingada. Em seguida, fale novamente com o Mestre de Frota Firalião a bordo do Véu Carmesim na costa da Selva do Espinhaço.",
    [4641] = "Fale com Gornek. Kaltunk marcou o paradeiro dele no mapa e mencionou que ele morava no Covil, ao oeste.",
    [4642] = "Leve uma Amostra de Gosma Amalgamada para o Químico Sérgio na Cidade Baixa.",
    [4681] = "Recupere a Carcaça de Tartaruga Marinha da Tartaruga Marinha Descarnada nas águas a oeste de Auberdine, e então fale com Gwennyth Bly'Leggonde em Auberdine.",
    [4701] = "Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs.",
    [4721] = "Trull Ruinazar em Selva Maleva quer que você cace 10 Ferujas Berserk em Hibérnia.",
    [4722] = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.",
    [4723] = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4724] = "Mate Halycon, senhora da matilha dos Worgs Machado Sangrento.",
    [4725] = "Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4726] = "Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.",
    [4727] = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.",
    [4728] = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4729] = "Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler.",
    [4730] = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4731] = "Leve a Caixa com Marcações Estranhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4732] = "Leve a Carcaça de Tartaruga Marinha para Gwennyth Bly'Leggonde em Auberdine.",
    [4733] = "Leve os Ossos de Criaturas Marinhas para Gwennyth Bly'Leggonde em Auberdine.",
    [4734] = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro.",
    [4735] = "Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes.",
    [4736] = "Fale com Menara Nihila nos Sertões.",
    [4737] = "Fale com Menara Nihila nos Sertões.",
    [4738] = "Fale com Menara Nihila nos Sertões.",
    [4739] = "Fale com Menara Nihila nos Sertões.",
    [4740] = "Encontre e mate o murloc conhecido como Lodofundo. Acredita-se que a criatura esteja defendendo as tendas dos murlocs ao sul de Auberdine, ao longo da costa. Relate a morte de Lodofundo à Sentinela Glynda Nal'Shea em Auberdine.",
    [4741] = "Trull Ruinazar em Selva Maleva quer que você cace 13 Ferujas Lunamarca.",
    [4742] = "Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan. Os generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento.",
    [4743] = "Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada. É nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser <rápido/rápida> para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!",
    [4761] = "Fale com Trovejius Tecevento em Auberdine.",
    [4762] = "Vá para o norte de Auberdine até a primeira queda d'água ao longo do Rio Fontescarpa e consiga uma amostra do charco. Leve a Amostra do Rio Fontescarpa para Trovejius Tecevento em Auberdine.",
    [4763] = "Encha a Bacia de Limpeza Vazia no Poço Lunar de Auberdine. Obtenha uma amostra de fruta, noz e grão dos acampamentos dos pelursos Bosquenero ao norte. Misture tudo na bacia e coloque junto à fogueira próxima ao Rio Fontescarpa, no acampamento norte. E assim atraia o sátiro corruptor. Pegue o Talismã de Corrupção e o leve para Trovejius Tecevento em Auberdine.",
    [4764] = "Leve o Broche do Finitudo para Mayara Asaluz nas Estepes Ardentes.",
    [4765] = "Leve a Caixote de Espargosa para o Conde Capistrano de Espargosa em Ventobravo.",
    [4766] = "Fale com Mayara Asaluz nas Estepes Ardentes.",
    [4767] = "Leve 10 Ovos de Mantícora de Alcândora para Elu, na Aldeia Vento Livre.",
    [4768] = "Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath.",
    [4769] = "Fale com a Umbramante Vivian Latumba.",
    [4770] = "Escolte Pae'ka Monte Veloz para fora de Alcândora, depois converse com Motega Barba de Fogo, no Posto Confinalvo.",
    [4771] = "Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco.",
    [4781] = "Leve uma Barra de Ouro para Xizk Pontobom, na Selva do Espinhaço.",
    [4782] = "Fale com Menara Nihila, nos Sertões.",
    [4783] = "Leve 10 Ampolas de Sangue de Furiódio e 1 Pedra Infernal Menor para Menara Nihila, nos Sertões.",
    [4784] = "Leve Fio de Ouro de Qualidade, 2 Carvões Fumegantes e um Estilhaço de Alma para Menara Nihila, nos Sertões.",
    [4786] = "Espere até Menara Nihila concluir a sua veste e depois fale novamente com ela.",
    [4787] = "Leve o Ovo Velho para Yeh'kinya, em Tanaris.",
    [4788] = "Leve a Quinta e a Sexta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris.",
    [4808] = "Leve a Carta de Vera para Felnok Molaço.",
    [4809] = "Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço.",
    [4810] = "Leve o Pacote do Felnok para Vera Brequim, nas Estepes Ardentes.",
    [4811] = "Viaje para o leste de Auberdine e procure por um grande cristal vermelho na montanha leste da Costa Negra. Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine.",
    [4812] = "Encha o Tubo de Água Vazio no poço lunar de Auberdine, e depois investigue o cristal vermelho na encosta da montanha leste da Costa Negra.",
    [4813] = "Relate o que você descobriu à Sentinela Glynda Nal'Shea, em Auberdine.",
    [4821] = "Leve o Ovo Alienígena a Hagar Casco de Raio, na Aldeia Vento Livre.",
    [4841] = "Mate 12 Batedores Galath, 10 Cavalgantes Galath e 6 Ventilhões Galath, depois fale novamente com o Vigia do Rochedo Chifre Longo na Aldeia Vento Livre.",
    [4842] = "Siga as instruções de Bruna Covaneve, depois fale novamente com ela.",
    [4861] = "Encontre o acampamento destruído e os suprimentos de Jaron Moldapedra na parte sul de Hibérnia.",
    [4862] = "Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler. Pelo nome, é de se pensar que eles fiquem perto das aranhas.",
    [4863] = "Encontre a carroça destruída de Jaron Moldapedra.",
    [4864] = "Pegue os Suprimentos do Jaron na neve, depois encontre o coruscante que roubou o amuleto de que Jaron falou. Entregue os Suprimentos do Jaron e o Amuleto de Penas Azuis para Jaron Moldapedra na cabana, em Hibérnia.",
    [4865] = "Relate suas descobertas a Motega Barba de Fogo.",
    [4866] = "No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenad<o/a> para que ele possa \"ordenhar\" você.",
    [4867] = "Leia o Pergaminho do Warosh. Traga o Mojo do Warosh para Warosh.",
    [4881] = "Alerte Kanati Nuvem Cinzenta, no Posto Confinalvo, do plano para assassiná-lo.",
    [4882] = "Leve o Colar de Penas Azuis para Trull Ruinazar, no Posto Peçonha.",
    [4883] = "Leve o Colar de Penas Azuis para Nara Juba Agreste.",
    [4901] = "Proteja Ranshalla enquanto ela tenta reativar o Altar de Eluna. Relate suas descobertas a Erelas Ambarcéu, na Vila de Rut'theran.",
    [4902] = "Fale com o Arquidruida Fandral Guenelmo em Darnassus.",
    [4903] = "Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida.",
    [4904] = "Escolte Lakota Cantéolo para fora do Pináculo da Nuvem Negra e depois fale com Thalia Couro Âmbar, na Aldeia Vento Livre.",
    [4906] = "Eridan Brisazul, na Selva Maleva, quer que você mate 8 Infernarautos Flamejade, 8 Traidores Flamejade, 8 Trapaceiros Flamejade e Xavaric. Fale novamente com Eridan quando a tarefa estiver concluída.",
    [4907] = "Fale com Vera Brequim.",
    [4921] = "Encontre a Mulher de Mankrik e depois fale novamente com ele na Encruzilhada.",
    [4941] = "Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall. Você se lembra de ter visto Eitrigg nos aposentos de Thrall.",
    [4961] = "Mate o Demônio do Orbe, depois fale com Tabetha.",
    [4962] = "Pegue o Rubi de Felhas e use-o em um dos Canisvis encontrados em Desolação. Depois de conseguir, leve o Rubi de Felhas e o Espírito de Canisvil Aprisionado de volta a Menara Nihila, nos Sertões.",
    [4963] = "Pegue a Esmeralda Infusa e use-a em um dos Infernais encontrados em Desolação. Depois de conseguir, leve a Esmeralda Infusa e o Espírito de Infernal Aprisionado de volta a Menara Nihila, nos Sertões.",
    [4964] = "Espere Menara Nihila completar o Orbe de Dar'Orathil e fale com ela novamente.",
    [4965] = "Fale com Menara Nihila nos Sertões.",
    [4966] = "Proteja Kanati Nuvem Cinzenta do ataque dos centauros.",
    [4967] = "Fale com Menara Nihila nos Sertões.",
    [4968] = "Fale com Menara Nihila nos Sertões.",
    [4969] = "Fale com Menara Nihila nos Sertões.",
    [4970] = "Colete 5 peças de Carne de Dentilhaços e 5 peças de Carne de Ventogelantes para Ripárion Glaciares, em Hibérnia.",
    [4971] = "Use o Deslocador Temporal perto de um dos silos de Andorhal e desencave Parasitas Temporais. Mate 15 Parasitas Temporais e depois devolva o Deslocador Temporal para Crona na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.",
    [4972] = "Encontre 5 Relógios de Andorhal, que estão em cofres em meio às ruínas da cidade. Regresse com eles até Crona, que está na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.",
    [4973] = "Encontre 5 Relógios de Andorhal em meio às ruínas da cidade e regresse com eles até Crona, que está na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais.",
    [4974] = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar.",
    [4975] = "Espere Menara Nihila completar o Orbe de Nor'Orahil e fale com ela novamente.",
    [4976] = "Leve o Orbe Infernal Purificado a Menara Nihila nos Sertões.",
    [4981] = "Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju.",
    [4982] = "Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade.",
    [4983] = "Leve o Relatório de Reconhecimento de Biju para o Grão-mestre Lexlort em Karrath.",
    [4984] = "Destrua 8 Lobos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.",
    [4985] = "Destrua 8 Ursos-cinzentos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais.",
    [4986] = "Baseado na magia imbuída no galho de carvalho com glifos, sua entrega ao Círculo Cenariano em Darnassus é o próximo passo que o druida tauren buscava. Procure a ajuda de um dos druidas.",
    [4987] = "Baseado na magia imbuída no galho de carvalho com glifos, sua entrega ao Círculo Cenariano no Penhasco do Trovão é o próximo passo que o druida Tauren buscava. Procure a ajuda de um dos druidas.",
    [5001] = "Encontre os Pertences de Biju e devolva-os a ela. Boa sorte!",
    [5002] = "Viaje para as Estepes Ardentes e dê as Informações de Biju para o Oficial Maxwell.",
    [5021] = "As divagações da mulher fantasmagórica indicavam que ela precisava que um pacote fosse entregue. Ela afirmou que ele estava no mesmo lugar que seu cavalo. Quanto ao local onde o cavalo está ou onde o pacote deve ser entregue, continua sendo impossível entender o fantasma.",
    [5022] = "Fale com os Administradores Reais de Ventobravo para saber o paradeiro da Bia Pedravil. Geralmente tem um agente do censo na Prefeitura.",
    [5023] = "Fale com os Feitores Reais da Cidade Baixa para saber o paradeiro da Jeremias Pedravil. Geralmente tem um agente do censo perto do registro de guilda e tabardo.",
    [5041] = "Encontre e devolva os Caixotes de Suprimentos da Encruzilhada a Thork, nos Sertões.",
    [5047] = "Fale com Málifus Trevamalho em Visteterna.",
    [5048] = "Encontre a Tia Bia em Ventobravo e veja se, de fato, ela é Bia Pedravil. Se for, talvez ela possa querer o pacote que Janice Pedravil lhe mandou.",
    [5049] = "Encontre a Jeremias Mascotte na Cidade Baixa e veja se, de fato, ele é Jeremias Pedravil. Se for, talvez ele possa querer o pacote que Janice Pedravil lhe mandou.",
    [5050] = "Devolva o Meio-pingente da Sorte para Janice Pedravil nas Terras Pestilentas Ocidentais.",
    [5051] = "Localize a outra metade do Pingente da Sorte em algum lugar da Fazenda Pedravil, nas Terras Pestilentas Ocidentais, e monte-o novamente. Dê o Pingente da Sorte a Janice Pedravil, na Fazenda Pedravil, que fica nas Terras Pestilentas Ocidentais.",
    [5052] = "Leve um Estilhaço de Sangue para Denterroto no Acampamento Taurajo, que fica nos Sertões. Colete mais Estilhaços de Sangue se você quiser que ele o abençoe com o poder de Agamaggan.",
    [5054] = "Ventania Casco Escuro, de Visteterna, Hibérnia, quer que você mate Úrsius.",
    [5055] = "Ventania Casco Escuro, de Visteterna, Hibérnia, quer que você mate Brumeran.",
    [5056] = "Ventania Casco Escuro, de Visteterna, Hibérnia, quer que você derrote Shy-Rotam.",
    [5057] = "Leve o Marcador de Ventania Casco Escuro para Melor Casco de Pedra no Penhasco do Trovão.",
    [5061] = "Volte a Darnassus e mostre a Mathrengyl Ursivagus o Pingente do Leão Marinho.",
    [5062] = "Reúna 10 punhados de Agave Incendia, depois consulte Magatha Temível Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5063] = "Para criar o Casquete do Sábio Escarlate, você precisa levar os seguintes itens para Málifus Trevamalho: 1 Pelego Imaculado da Fera; 5 Suturas de Abominação Puídas; 8 Cristais Arcanos; 5 Fios Escarlate Encantados. Você também deverá pagar 50 ouros pela fabricação do item.",
    [5064] = "Localize e recupere os três Bilhetes Secretos no Pináculo da Nuvem Negra.",
    [5065] = "Leve a Terceira e a Quarta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris.",
    [5066] = "Procure o Comandante Ashlam Punhobom. Ele montou base no Acampamento Ventogelante, ao norte das Montanhas de Alterac.",
    [5067] = "Para criar as Perneiras do Arcanismo, você precisa levar os seguintes itens para Málifus Trevamalho: 1 Pelego Imaculado da Fera; 5 Suturas de Abominação Puídas; 5 Barras de Arcanita; 5 Fluidos Embalsamadores de Friomúrmuro. Você também deverá pagar 50 ouros pela fabricação do item.",
    [5068] = "Para criar o Peitoral da Sede de Sangue, você precisa levar os seguintes itens para Málifus Trevamalho: 1 Pelego Imaculado da Fera; 10 Suturas de Abominação Puídas; 5 Barras de Arcanita; 5 Peles de Sombra. Você também deverá pagar 50 ouros pela fabricação do item.",
    [5081] = "Vá para o Pico da Rocha Negra e mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. Fale novamente com o Oficial Maxwell quando terminar o trabalho.",
    [5082] = "Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos.",
    [5083] = "Leve o Frasco Vazio de Aguardente para Bruna Covaneve em Hibérnia.",
    [5084] = "Investigue o acampamento dos pelursos Lenha Morta na parte norte de Selva Maleva para encontrar alguma pista.",
    [5085] = "Informe Bruna Covaneve sobre as suas descobertas.",
    [5086] = "Colha 3 Gotinhas de Horror Tóxico para Bruna Covaneve em Hibérnia.",
    [5087] = "Encontre os Mensageiros Invernosos e impeça-os de entregar o carregamento à Aldeia dos Invernosos.",
    [5088] = "Mate Arikara. Leve seus restos mortais e o Pó de Incendia a Motega Barba de Fogo no Posto Confinalvo como prova do seu feito.",
    [5089] = "Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes.",
    [5090] = "Procure o Comandante Ashlam Punhobom. Ele montou base no Acampamento Ventogelante, ao norte das Montanhas de Alterac.",
    [5091] = "Procure o Comandante Ashlam Punhobom. Ele montou base no Acampamento Ventogelante, ao norte das Montanhas de Alterac.",
    [5092] = "Mate 10 Esfoladores Descarnados e 10 Carniçais Salivantes na Colina do Pesar. Fale novamente com o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5093] = "Procure o Alto-executor Arcabuz. A base de operações dele fica no Baluarte, a leste das Clareiras de Tirisfal e da Cidade Baixa.",
    [5094] = "Procure o Alto-executor Arcabuz. A base de operações dele fica no Baluarte, a leste das Clareiras de Tirisfal e da Cidade Baixa.",
    [5095] = "Procure o Alto-executor Arcabuz. A base de operações dele fica no Baluarte, a leste das Clareiras de Tirisfal e da Cidade Baixa.",
    [5096] = "Vá até a base de operações da Cruzada Escarlate, que fica entre o Campo Pedravil e as Lágrimas de Dalson, e destrua a Tenda de Comando. Plante a bandeira do Flagelo no acampamento e fale novamente com o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais.",
    [5097] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la. Depois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Comandante Ashlam Punhobom no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5098] = "Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la. Depois de marcar as quatro torres, leve a Tocha Sinalizadora de volta para o Alto-executor Arcabuz no Baluarte, nas Terras Pestilentas Ocidentais.",
    [5102] = "Viaje de volta ao Pico da Rocha Negra e destrua o General Drakkisath. Depois, fale novamente com o Oficial Maxwell.",
    [5103] = "Alguém neste mundo deve saber o fazer com essas manoplas. Boa sorte!",
    [5121] = "Bruna Covaneve em Hibérnia quer que você derrote o Chefe Supremo Invernoso.",
    [5123] = "Leve o Registro Escrito Grosseiramente para Bruna Covaneve em Hibérnia.",
    [5124] = "Leve 6 Barras de Tório Encantado, 2 Essências do Fogo e 4 Rubis-estrela para Málifus Trevamalho. Você também vai ter que entregar suas Manoplas de Placa Crua.",
    [5126] = "Fale com Vegax. Escute o que ele tem a dizer.",
    [5127] = "Viaje para o Pico da Rocha Negra e encontre Goraluk Rachadastra. Mate-o e use o Pique Manchado de Sangue no cadáver dele. Quando a alma dele tiver sido canalizada, o pique ficará Manchado de Almas. Você também precisa encontrar o Peitoral Rúnico de Metal Bruto. Leve o Pique Manchado de Almas e o Peitoral Rúnico de Metal Bruto para Vegax, em Hibérnia.",
    [5128] = "Leve o Registro Escrito Grosseiramente para Kelek Guardacéus, na parte sul da Selva Maleva.",
    [5141] = "Leve 2 Peitorais Escorpídeos Resistentes, 2 Luvas Escorpídeas Resistentes e 10 Escamas Gastas de Dragão para Pedro Galho em Azshara. Completar essa missão lhe dará acesso à arte da Couraria Dragônica. Completar a missão impedirá que você aprenda Couraria Elemental e Couraria Tribal; tenha certeza de que esta é a trilha que você deseja seguir antes de fazer sua escolha.",
    [5142] = "Encontre Pâmela Trilharrubra.",
    [5143] = "Leve um Colete de Couro Silvestre e um Capacete de Couro Silvestre para Caryssia Caçaluna em Feralas. Ao completar essa missão, você terá acesso às artes de Couraria Tribal. A conclusão da missão irá <impedí-lo/impedí-la> de aprender Couraria Dragônica e Couraria Elemental. Certifique-se que este é o caminho que deseja seguir antes de continuar.",
    [5144] = "Traga 2 Corações de Fogo, 2 Globos de Água, 2 Núcleos da Terra e 2 Sopros Eólicos para Sarah Tanner na Garganta Abrasadora. Ao cumprir esta missão, você terá acesso à arte da Couraria Elemental. Com isso, você não poderá aprender Couraria Dragônica e Couraria Tribal. Por isso, antes de escolher este caminho, é preciso ter certeza de que é isso que você realmente quer.",
    [5145] = "Leve 2 Peitorais Escorpídeos Resistentes, 2 Luvas Escorpídeas Resistentes e 10 Escamas Gastas de Dragão para Thorkaf Olho-de-tigre em Azshara. O cumprimento desta missão lhe dará acesso à arte da Couraria Dragônica. Por outro lado, isso também impedirá que você aprenda Couraria Elemental e Couraria Tribal. Certifique-se de que esse é o caminho que você deseja seguir antes de fazer sua escolha.",
    [5146] = "Leve 2 Corações de Fogo, 2 Globos de Água, 2 Núcleos da Terra e 2 Sopros Eólicos para Brum Casco Invernal em Pedre'gor, que fica no Planalto Arathi. Ao cumprir esta missão, você terá acesso à arte da Couraria Elemental. Com isso, você não poderá aprender Couraria Dragônica e Couraria Tribal. Tenha certeza de que é este o caminho que deseja seguir.",
    [5147] = "Mate Arnak Temível Totem e leve uma prova de seu feito para o Vigia do Rochedo Chifre Longo, na Aldeia Vento Livre.",
    [5148] = "Leve um Colete de Couro Silvestre e um Capacete de Couro Silvestre para Se'Jib, na Selva do Espinhaço. Ao cumprir a missão, você terá acesso às artes da Couraria Tribal. Ao cumprir a missão, o aprendizado de Couraria Dragônica e Couraria Elemental lhe será proibido. Tenha certeza de sua escolha antes de tomar o passo que está prestes a dar.",
    [5149] = "Encontre a boneca de Pâmela.",
    [5151] = "Mate a fera e traga de volta o Dispositivo Hipercapacitador e a Chave da Jaula da Pantera para Vizlo Limpajunta.",
    [5152] = "Fale com Marlene, ao sul das Ruínas de Andorhal.",
    [5153] = "Leve o Anel de Casamento do Josefo para Crona.",
    [5154] = "Leve os Anais da Vila das Flechas para Crona em Andorhal.",
    [5155] = "Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva.",
    [5156] = "Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva.",
    [5157] = "Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva.",
    [5158] = "Leve a Água Corrompida do Poço Lunar para Islen Vidente da Água, nos Sertões.",
    [5159] = "Leve a Água Purificada do Poço Lunar para Greta Musgo no Casco, na Selva Maleva.",
    [5160] = "Viaje para Hibérnia e encontre Haleh. Entregue para ela a Escama do Albi.",
    [5161] = "Fale com Haleh se quiser continuar.",
    [5162] = "Fale com Jezibá nas Terras Pestilentas. Ele mora em Andorhal.",
    [5163] = "Leve o Yeti Mecânico da Umi e assuste os amigos dela: Legacki, em Visteterna (Hibérnia), Sguisha, em Geringontzan (Tanaris) e Quixxil, no Refúgio do Marshal (Cratera Un'Goro). Quando terminar, leve o Yeti Mecânico de volta para Umi.",
    [5164] = "Leia o Catálogo do Imprevisível.",
    [5165] = "Use a Água Purificada do Poço Lunar para extinguir os quatro braseiros de proteção no interior da Fortaleza do Concílio das Sombras, em Selva Maleva, depois fale novamente com Greta Musgo no Casco, no Santuário Esmeralda.",
    [5166] = "Para forjar o Peitoral da Revoada Cromática, você deverá levar os seguintes itens para Jezibá, o Escultor: 1 Carapaça Cromática. 10 Escamas Cromáticas Brilhantes. 10 Sangues dos Heróis. 10 Suturas de Abominação Puídas.",
    [5167] = "Para forjar os Coxotes do Desafiante Cromático, você deverá levar os seguintes itens para Jezibá, o Escultor: 1 Carapaça Cromática. 10 Escamas Cromáticas Brilhantes. 10 Sangues de Heróis. 5 Peles de Sombra.",
    [5168] = "Leve o Incunábulo de Davil e o Escudo de Trilharrubra para Carlin Trilharrubra.",
    [5181] = "Leve o Crânio de Horgus e a Espada Estilhaçada de Marduk para Carlin Trilharrubra na Capela Esperança da Luz.",
    [5201] = "Ripárion Glaciares quer que você mate 5 Xamãs Invernosos e 5 Ursinos Invernosos.",
    [5202] = "Procure em Jaedenar o que pode ser aberto pela Chave Vermelho Sangue.",
    [5203] = "Escolte Arko'narin até onde Forjaleve e o equipamento dela estão, e então a proteja enquanto escapam da Fortaleza do Concílio das Sombras. Depois, procure Jessir Lunarco em Selva Maleva para informá-la sobre o que houve com os amigos dela.",
    [5204] = "Volte a Jaedenar e mate o súcubo Rakaiah antes de encontrar os Restos Mortais de Trey Forjaleve.",
    [5206] = "Leve 5 Crânios Ressonantes e o Cristal Místico para Carlin Trilharrubra nas Terras Pestilentas Orientais.",
    [5210] = "Leve os Anais Estendidos da Vila das Flechas para Carlin Trilharrubra nas Terras Pestilentas Orientais.",
    [5211] = "Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.",
    [5212] = "Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.",
    [5213] = "Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco.",
    [5214] = "Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço.",
    [5215] = "Fale com a Alta-sacerdotisa Donélia no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5216] = "Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5217] = "Leve a Garrafa do Campo Pedravil Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5219] = "Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5220] = "Leve a Garrafa das Lágrimas de Dalson Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5222] = "Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5223] = "Leve a Garrafa do Antro Repelente Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5225] = "Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5226] = "Leve a Garrafa da Aridez de Garrão Cheia à Alta-sacerdotisa Donélia no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5228] = "Fale com a Sacerdotisa Sombria Vandis, em Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5229] = "Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5230] = "Leve a Garrafa do Campo Pedravil Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5231] = "Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5232] = "Leve a Garrafa das Lágrimas de Dalson Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5233] = "Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5234] = "Leve a Garrafa do Antro Repelente Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5235] = "Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão.",
    [5236] = "Leve a Garrafa da Aridez de Garrão Cheia à Sacerdotisa Sombria Vandis em Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5241] = "Encontre Carlin Trilharrubra.",
    [5242] = "Mate Moora e Salia, e leve a Cabeça do Lorde das Sombras Fel'dan para Greta Musgo no Casco em Selva Maleva.",
    [5243] = "Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente.",
    [5244] = "Fale com Jaron Moldapedra na Aldeia Chuva Estelar.",
    [5245] = "Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais.",
    [5246] = "Encontre os Escritos Sagrados dos Altaneiros no Templo de Zin-Malor, em Azshara, e leve-os para Aurora Clamacéus, perto da Torre do Passo Norte nas Terras Pestilentas Orientais.",
    [5247] = "Leve uma Barra de Tório Encantado, 5 Restaurações de Cristal e uma Ampola de Água Hedionda para Aurora Clamacéus perto da Torre do Passo Norte nas Terras Pestilentas Orientais.",
    [5248] = "Leve o Cristal de Zin-Malor ao Lago Kel'Theril, em Hibérnia, e encontre o espírito de um altaneiro que fale com você.",
    [5249] = "Encontre a Aldeia Chuva Estelar, em Hibérnia, e fale com Eol Correnoite.",
    [5250] = "Encontre a Chuva Estelar, em Hibérnia, e fale com Eol Correnoite.",
    [5251] = "Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.",
    [5252] = "Fale com Eol Correnoite na Aldeia Chuva Estelar e pergunte qual é o lugar mais apropriado para o Cristal de Zin-Malor.",
    [5253] = "Leve o Cristal de Zin-Malor para o Arquidruida Fandral Guenelmo em Darnassus.",
    [5261] = "Fale com Enzo Peleteiro.",
    [5262] = "Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais.",
    [5263] = "Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff.",
    [5264] = "Fale com o Lorde Maximiliano Tyrosus. Ele está dentro da igreja.",
    [5265] = "Abra o Castelo Violeta e reivindique sua recompensa.",
    [5281] = "Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme.",
    [5282] = "Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade! Liberte 15 Almas Inquietas, depois fale novamente com Egan.",
    [5283] = "Para virar Ferreir<o/a> de Armaduras, tu vai ter que forjar os seguintes itens e levá-los pro Grumnus: quatro Elmos Ornados de Mithril, duas Botas Ornadas de Mithril e um Peitoral Ornado de Mithril.",
    [5284] = "Para te tornares Armeir<o/a>, tu terás que forjar os seguintes itens e trazer para o Ironus: 4 Espadas Largas de Lunaço, 4 Machados Sólidos de Ferro, 2 Machados Pesados de Mithril e 2 Grandes Maças Pretas.",
    [5301] = "Para virar Ferreir<o/a> de Armaduras, você vai ter que forjar os seguintes itens e levá-los para Okothos: quatro Elmos Ornados de Mithril, duas Botas Ornadas de Mithril e um Peitoral Ornado de Mithril.",
    [5302] = "Para se tornar <um Armeiro/uma Armeira>, você precisa fazer os seguintes itens e levá-los para Borgosh: 4 Espadas Largas de Lunaço, 4 Machados Sólidos de Ferro, 2 Machados Pesados de Mithril e 2 Grandes Maças Pretas.",
    [5305] = "Vá para Stratholme e mate o Forjador de Martelos Carmesim. Recolha o Avental do Forjador de Martelos Carmesim e leve-o para Lilith.",
    [5306] = "Vá para o Pico da Rocha Negra e mate a Caçadora Sombria Vosh'gajin. Recolha a Litofídia de Vosh'gajin e fale novamente com Kilram.",
    [5307] = "Encontre o Cuteleiro da Guarda Negra em Stratholme e destrua-o. Recolha a Insígnia da Guarda Negra e fale novamente com Seril Flagelicida.",
    [5321] = "Escolte Kerlonian Perenumbra até Liladris Luneflúvia pela estrada sul para encontrar a bolsa dele na Costa Negra.",
    [5341] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa.",
    [5342] = "Vá para o Acampamento Ventogelante, no território da Aliança, e assassine Weldon Barov. Recolha a cabeça dele e fale novamente com Alexei Barov. Esteja avisad<o/a>: Weldon provavelmente estará muito bem protegido pela escória da Aliança.",
    [5343] = "Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa.",
    [5344] = "Vá para o Baluarte, no território da Horda, e assassine Alexei Barov. Recolha a cabeça dele e fale novamente com Weldon Barov. Esteja avisad<o/a>: Alexei provavelmente estará muito bem protegido pela escória da Horda.",
    [5361] = "Leve o Relatório de Vigia do Rochedo Chifre Longo para Nataoka Chifre Longo no Entreposto do Espírito que Anda, situado em Desolação.",
    [5381] = "Recolha a Caixa Demoníaca na Fortaleza Machado do Trovão e leve-a, junto com a Picareta do Diabo, para Taiga Crina Sábia na Aldeia Pescassombra.",
    [5382] = "Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa.",
    [5384] = "Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma. Lute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff.",
    [5385] = "Entregue os Restos Mortais de Trey Forjaleve a Jessir Lunarco, em Selva Maleva.",
    [5386] = "Converse com Jinar'Zillen, na Aldeia Pescassombra, e depois leve 2 peixes pança-sangrenta para Nataoka Chifre Longo.",
    [5441] = "Use o Cassetete do Encarregado nos Peões Preguiçosos enquanto estiverem dormindo. Acorde 5 peões, depois devolva o Cassetete do Encarregado ao Encarregado Thazz'ril, no Vale das Provações.",
    [5461] = "Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque.",
    [5462] = "Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu.",
    [5463] = "Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado.",
    [5464] = "Leve a Lembrança Vinculada para Leonid Bartolomeu, nas Terras Pestilentas Orientais.",
    [5465] = "Fale novamente com o Magistrado Marduque, no Castro das Flechas. Mostre-lhe a Lembrança Vinculada.",
    [5466] = "Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque.",
    [5481] = "Colha 3 Ervas-do-emo e entregue para o Boticário-júnior Hollanda, no cemitério de Montalvo.",
    [5482] = "Colha 10 Ervas-do-demo e entregue para o Boticário-júnior Hollanda.",
    [5501] = "Entregue 10 Ossos de Kodo do Cemitério dos Kodos para Bibbly Ferrafivela no Barraco do Kormek.",
    [5504] = "Leve 10 Símbolos de Bravura da Aurora Argêntea à Intendente Hasana, no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5507] = "Leve 10 Símbolos de Bravura da Aurora Argêntea ao Intendente Centelhuz, no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5513] = "Leve 10 Símbolos de Bravura da Aurora Argêntea à Intendente Cerraculatra, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.",
    [5514] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan.",
    [5515] = "Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff.",
    [5517] = "Leve 25 Símbolos de Bravura da Aurora Argêntea à Intendente Cerraculatra, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.",
    [5518] = "Leve 4 Peças de Runatrama, 8 Couros Rústicos, 2 Fios Rúnicos e Tanino Ôgrico para Fiapo Agulhacerta. Atualmente, ele está acorrentado dentro da ala Gordok do Gládio Cruel.",
    [5521] = "Leve 25 Símbolos de Bravura da Aurora Argêntea ao Intendente Centelhuz, no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5522] = "Leve os Ovos Congelados para Leonid Bartolomeu, nas Terras Pestilentas Orientais.",
    [5524] = "Leve 25 Símbolos de Bravura da Aurora Argêntea à Intendente Hasana, no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5526] = "Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua.",
    [5527] = "Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua.",
    [5529] = "Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz.",
    [5531] = "Leve os Ovos Congelados para Betina Bigozinco.",
    [5533] = "Fale com o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5534] = "Encontre Essa Tal Runa que está com as nagas nas Ruínas de Eldarath e traga-a para Kam'arawn, em Azshara.",
    [5535] = "Destrua 6 Aparições Altaneiras e 6 Subliches Altaneiros. Depois, fale com Loh'atu em Azshara.",
    [5536] = "Mate 6 Sátiros Haldarr, 2 Trapaceiros Haldarr e 2 Devotos Vil Haldarr. Depois, fale novamente com Loh'atu na fronteira do Vale Gris.",
    [5537] = "Leve 15 Fragmentos de Ossos para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5538] = "Leve os Fragmentos de Ossos Imbuídos e 15 moedas de ouro para Rugov A. Massoaço em Geringontzan.",
    [5541] = "Entregue a Munição do Estremetiro para Hegnar Estremetiro em Dun Morogh.",
    [5542] = "Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída.",
    [5543] = "Mate 30 Quirópragos e fale novamente com Tirion Fordring.",
    [5544] = "Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro.",
    [5545] = "Leve 8 Feixes de Madeira para Raquel na Madeireira Vale do Leste.",
    [5561] = "Leve cinco Kodos Domados e o Kodoagrupandador para Smid Rabiscafuso no Acampamento do Rabiscafuso.",
    [5581] = "Feche 6 portais nas Ruínas de Mannoroc e fale com Taiga Crina Sábia na Aldeia Pescassombra.",
    [5582] = "Leve a Escama de Dragão Saudável para Betina Bigozinco na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.",
    [5601] = "Encontre Pâmela Trilharrubra na Vila das Flechas.",
    [5621] = "Encontre a Sentinela Shaya e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ela Palavra de Poder: Fortitude e fale novamente com Laurna Luzalbor em Dolanaar.",
    [5622] = "Fale com Laurna Luzalbor em Teldrassil.",
    [5623] = "Fale com a Sacerdotisa Joselita na Floresta de Elwynn.",
    [5624] = "Encontre a Guarda Roberts e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com a Sacerdotisa Joselita em Vila d'Ouro.",
    [5625] = "Encontre o Montanhista Dolf e cure suas feridas usando Cura Inferior (Grau 2). Depois disso, conceda a ele Palavra de Poder: Fortitude e fale novamente com Maxan Begurno em Kharanos.",
    [5626] = "Fale com Maxan Begurno em Dun Morogh.",
