    [5713] = "Proteja a Sentinela Aynasha. Em seguida, fale com Onaeya no Entreposto de Maestra, que fica no Vale Gris.",
    [5721] = "Coloque o Saco de Relíquias na praça da Vila das Flechas. Impeça que Davil Luminoso morra antes de Horgus. Impeça que o Capitão Trilharrubra morra antes que Trilharrubra, o Corrompido, surja. Derrote Trilharrubra, o Corrompido. Fale com o espírito de Josefo Trilharrubra quando ele aparecer na praça, depois fale com Pâmela na casa dela.",
    [5722] = "Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse.",
    [5723] = "Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão.",
    [5724] = "Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão.",
    [5725] = "Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa.",
    [5726] = "Leve uma Insígnia do Tenente para Thrall em Orgrimmar.",
    [5727] = "Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar.",
    [5728] = "Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar.",
    [5729] = "Fale com Neeru Cortafogo em Orgrimmar.",
    [5730] = "Fale com Thrall em Orgrimmar e conte a ele o que você descobriu.",
    [5741] = "Pegue o Cetro de Luz e devolva-o para Azore Albamorte na torre de Ethel Rethor.",
    [5742] = "Escute o que Tirion Fordring tem a dizer.",
    [5761] = "Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar.",
    [5762] = "Leve o Caixote de Kravel para Rosarães Guima na Selva do Espinhaço.",
    [5763] = "Leve o Chifre de Kodo de Roon para Rosarães Guima na Selva do Espinhaço.",
    [5781] = "Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo.",
    [5801] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada. Leve a Chave-mestra Inacabada para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5802] = "Leve o Molde de Chave-mestra e 2 Barras de Tório para o topo do Pico Penacho de Fogo, na Cratera Un'Goro. Use o Molde de Chave-mestra no lago de lava para forjar a Chave-mestra Inacabada. Leve a Chave-mestra Inacabada para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5803] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [5804] = "Destrua Araj, o Evocador e leve o Escaravelho de Araj para o Boticário Trépido no Baluarte, que fica nas Terras Pestilentas Ocidentais.",
    [5821] = "Escolte a Caravana Gizelton pela aldeia dos Centauros Kolkar. Fale com o Smid no Acampamento do Rabiscafuso para receber a recompensa.",
    [5845] = "Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo.",
    [5846] = "Viaje para a ilha de Castro das Flechas, na região centro-sul das Terras Pestilentas, e procure pistas sobre o paradeiro da pintura.",
    [5848] = "Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo. Leve a pintura de volta para Tirion Fordring.",
    [5861] = "Viaje para a Tumba de Uther, que fica nas Terras Pestilentas meridionais. Mostre a Dádiva de Tirion para Myranda, a Bruxa Velha.",
    [5862] = "Fale com Myranda para receber a Ilusão Escarlate. Viaje para Amparo sob o efeito de Ilusão Escarlate e entregue a Dádiva de Tirion para o Grão-lorde Taelan Fordring. Amparo fica ao norte e Taelan estará dentro da Bastilha Mardenforte.",
    [5863] = "Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador.",
    [5881] = "Maggran quer que você entregue uma carta a Grish Pisaléguas no Grande Elevador, que fica nos Sertões.",
    [5892] = "Leve 10 Suprimentos de Ferrofundo para o Intendente da Aliança em Dun Baldar.",
    [5893] = "Leve 10 Suprimentos de Dentefrio para o Intendente da Horda na Bastilha Lobo do Gelo.",
    [5901] = "Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Guel Levine no Baluarte, nas Clareiras de Tirisfal.",
    [5902] = "Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.",
    [5903] = "Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Nataniel Dumah no Acampamento Ventogelante, em Terras Pestilentas Ocidentais.",
    [5904] = "Encontre um lugar apropriado para pôr o Barril de Cupins das Terras Pestilentas no centro da Serraria de Beiranorte, que fica nas Terras Pestilentas Ocidentais.",
    [5921] = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.",
    [5922] = "Use o feitiço \"Teleporte: Clareira da Lua\" para viajar para a Clareira da Lua. Ao chegar, fale com Dendrite Stellardor, no vilarejo de Refúgio Noturno.",
    [5923] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5924] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5925] = "Fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [5926] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5927] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5928] = "Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão.",
    [5929] = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",
    [5930] = "Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",
    [5931] = "Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano.",
    [5932] = "Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos.",
    [5941] = "Leve a Coleção de Relíquias para Crona em Andorhal.",
    [5942] = "Leve a Chave de Josefo ao Baú de Josefo.",
    [5943] = "Escolte a Caravana Gizelton pelas Ruínas de Mannoroc. Fale com o Smid no Acampamento do Rabiscafuso para receber a recompensa.",
    [5944] = "Escolte Taelan Fordring para fora de Amparo.",
    [5961] = "Fale com Nathanos, o Arauto da Praga nas Terras Pestilentas Orientais. Dizem que ele fixou residência no Sítio dos Marris.",
    [5981] = "Ripárion Glaciares quer que você mate 4 Gigantes Friomalho e 4 Preservadores Friomalho.",
    [6001] = "Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. Fale com Mathrengyl Ursivagus em Darnassus quando você terminar.",
    [6002] = "Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. Fale com Turak Runa Totem no Penhasco do Trovão quando terminar.",
    [6004] = "Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",
    [6021] = "Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz.",
    [6022] = "Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada.",
    [6023] = "Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",
    [6024] = "Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta.",
    [6025] = "Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais.",
    [6026] = "Leandro Leonardo quer que você pegue 2 Barras de Tório, 1 Bastão Dourado, 8 Bombas de Alto-explosivo e 8 Gatilhos Instáveis. Você terá que encontrar um ferreiro e um engenheiro para esses itens.",
    [6027] = "Pegue o Livro dos Anciãos e entregue-o para Azore Albamorte na torre de Ethel Rethor.",
    [6028] = "Entregue o Relatório de Visteterna à Oficial Argêntea Cândida no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [6029] = "Entregue o Relatório de Visteterna ao Oficial Argênteo Garush no Baluarte, nas Terras Pestilentas Ocidentais.",
    [6030] = "Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais.",
    [6031] = "Leve 30 cortes de Runatrama para Meilosh no Domínio dos Presamatos.",
    [6032] = "Leve 2 cortes de Lunatrama para Meilosh no Domínio dos Presamatos.",
    [6041] = "Viaje ao Bosque Pestilento, a noroeste da Esperança da Luz. Destrua 8 Estruturas do Flagelo usando o Composto Químico Especial do Leandro na Marca de Detonação plantada dentro de cada construção. Os Zigurates e Abatedouros foram marcados por instrução de Leandro. Assim que você plantar a bomba, deixe a estrutura e contemple seu trabalho. A propósito, o Composto Químico Especial do Leandro é bastante... instável.",
    [6042] = "Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado.",
    [6061] = "Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6062] = "Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",
    [6063] = "Use o Bastão de Adestramento para domar uma Tocaieira Lenhateia. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6064] = "Use o Bastão de Adestramento para domar uma Rochetusco Grande. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",
    [6065] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6066] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6067] = "Fale com Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6068] = "Fale com Thotar no Monte Navalha.",
    [6069] = "Fale com Thotar no Monte Navalha.",
    [6070] = "Fale com Thotar no Monte Navalha.",
    [6071] = "Fale com Dazalar em Dolanaar.",
    [6073] = "Fale com Dazalar em Dolanaar.",
    [6074] = "Fale com Grif Selvacuore em Kharanos.",
    [6075] = "Fale com Grif Selvacuore em Kharanos.",
    [6076] = "Fale com Grif Selvacuore em Kharanos.",
    [6081] = "Fale com Ormak Tiroatroz em Orgrimmar.",
    [6082] = "Use o Bastão de Adestramento para domar um Escorpídeo Encouraçado. Pratique sua habilidade e depois fale novamente com Thotar no Monte Navalha.",
    [6083] = "Use o Bastão de Adestramento para domar uma Surfatisco. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",
    [6084] = "Use o Bastão de Adestramento para domar uma Leopardo da Neve. Pratique sua habilidade e depois fale novamente com Grif Selvacuore em Kharanos.",
    [6085] = "Use o Bastão de Adestramento para domar um Urso Garra de Gelo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",
    [6086] = "Fale com Bélia Granitrondo em Altaforja.",
    [6087] = "Use o Bastão de Adestramento para domar um Espreitador-da-pradaria. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6088] = "Use o Bastão de Adestramento para domar uma Rapineiro. Pratique sua habilidade e depois devolva o Bastão a Yaw Crina Cortante na Aldeia Casco Sangrento.",
    [6089] = "Fale com Holto Chifre Troante no Platô dos Caçadores, que fica no Penhasco do Trovão.",
    [6101] = "Use o Bastão de Adestramento para domar um Espreitador Sabre-da-noite. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6102] = "Use o Bastão de Adestramento para domar uma Guinchadora Estrígida. Treine sua perícia, e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",
    [6103] = "Fale com Jocasta no Enclave Cenariano, que fica em Darnassus.",
    [6121] = "Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno.",
    [6122] = "Use o Coletor Vazio das Quedas de Fontescarpa para coletar uma amostra de água da entrada da caverna da cachoeira. Entregue o Coletor Cheio das Quedas de Fontescarpa para Alanndária Noturcanto em Auberdine, na Costa Negra.",
    [6123] = "Leve 5 Raízes-telúricas e 12 Fungos Lunares para Alanndária Noturcanto em Auberdine para que ela possa preparar o bálsamo curativo.",
    [6124] = "Use o Bálsamo Curativo para Animais em 10 Cervos Adoentados espalhados pela Costa Negra. Isso deve curá-los. Cervos Adoentados foram avistados da região ao sul do Rio Fontescarpa, seguindo até a área ao norte de Auberdine, até a Costa Negra meridional, na fronteira do Vale Gris.",
    [6125] = "Fale novamente com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [6126] = "Vá à Clareira da Lua e fale com Dendrite Stellardor no vilarejo de Refúgio Noturno.",
    [6127] = "Use o Coletor Vazio do Morro de Brumedo para obter uma amostra de água de um lago no topo do morro. Entregue o Coletor Cheio do Morro de Brumedo a Tonga Runa Totem na Encruzilhada, nos Sertões.",
    [6128] = "Leve 5 Raízes-telúricas e 5 Chifres de Kodo para Tonga Runa Totem na Encruzilhada para que ele possa preparar um bálsamo curativo.",
    [6129] = "Use o Bálsamo Curativo para Animais em 10 Gazelas Doentes espalhadas pelo norte dos Sertões. Isso deve curá-las. Gazelas Doentes foram avistadas por toda parte a norte da estrada leste-oeste, que atravessa a Encruzilhada.",
    [6130] = "Fale novamente com Turak Runa Totem no Platô dos Anciãos, no Penhasco do Trovão.",
    [6132] = "Escolte Melizza Zumbidorla e depois fale com Guido Zumbidorla no Cemitério dos Kodos, na Desolação.",
    [6133] = "Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien. Você também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros.",
    [6134] = "Leve 8 Fantasmoplasmas e o Caixote de Ímãs Fantasmais para Guido Zumbidorla na Desolação.",
    [6135] = "Encontre Quiroscuro e mate-o. Do cadáver, extraia um Tufo de Pele de Quiroscuro e leve para Nathanos Arauto da Praga. Dizem que Quiroscuro vaga pelo campo ao norte do Sítio dos Marris.",
    [6136] = "Encontre Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o. Fale novamente com Nathanos Arauto da Praga quando tiver cumprido a missão.",
    [6141] = "Fale com o Irmão Anton na Desolação.",
    [6142] = "Encontre 10 nacos de Carne de Marisco de Casca Mole e entregue-os para Mai'Lahii na Aldeia Pescassombra.",
    [6143] = "Mate 7 Mirmidões Sibilâmina, 7 Nagas Sibilâmina e 5 Feiticeiras Sibilâmina. Em seguida, fale com Drulzeger, na Aldeia Pescassombra, em Desolação.",
    [6144] = "Vá à Cidade Baixa e fale com Varimatras.",
    [6145] = "Volte às Terras Pestilentas Orientais e rastreie o Mensageiro Carmesim. Mate o mensageiro e obtenha as Ordens do Grão-cruzado. Leve-as para Nathanos Arauto da Praga para obter suas próximas instruções.",
    [6146] = "Vá à Manopla de Tyr, a sudeste do Sítio dos Marris. Quando chegar lá, coma um pedaço da Maçã Podre. Com o disfarce da Cruzada Escarlate, entregue as Ordens do Grão-cruzado ao Lorde Cruzado Valdelmar.",
    [6147] = "Fale novamente com Nathanos Arauto da Praga para repassar a ele as novas informações.",
    [6148] = "A Cruzada Escarlate está em marcha. Em algum ponto da estrada da Manopla de Tyr para Stratholme estará o Oráculo, Demétria, e a comitiva dela. Encontre-a e mate-a. Fale novamente com Nathanos Arauto da Praga se tiver sucesso.",
    [6161] = "Encontre a Chave Prateada de Rodovalho e a Chave Dourada de Rodovalho. Encontre e abra o Baú de Rodovalho.",
    [6162] = "Mate o Suserano Ror e leve a garra dele para Dreka'Sur no Posto Peçonha, na Selva Maleva.",
    [6163] = "Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos.",
    [6164] = "Leve o Livro-caixa do Augustus para Augustus, o Pirado, na Várzea do Medo.",
    [6181] = "Mostre o Bilhete do Ludovico a Thor, o mestre de grifos.",
    [6182] = "Fale com Mathias Shaw na Cidade Velha de Ventobravo. Ele mora no Quartel.",
    [6183] = "Fale com Mathias Shaw novamente se desejar aceitar esta tarefa.",
    [6184] = "Vá até o Acampamento Ventogelante, nas Terras Pestilentas Ocidentais, e encontre seu contato, Flint Umbramais.",
    [6185] = "Vasculhe as Terras Pestilentas Orientais em busca de pistas sobre o \"Arauto da Praga\" e os agentes da AVIN desaparecidos. Ser encontrar alguma Insígnia da AVIN, leve de volta para Flint Umbramais, no Acampamento Ventogelante.",
    [6186] = "Retorne a Ventobravo e informe o Grão-lorde Bolvar Fordragon sobre o destino de Nathanos Marris.",
    [6187] = "Reúna um exército e siga até as Terras Pestilentas Orientais. Lance um ataque maciço contra Nathanos Arauto da Praga e qualquer lixo da Horda que tente protegê-lo. Mantenha-se sempre alerta, <name>. Os membros da Horda vão defender o lorde patrulheiro com as próprias vidas.",
    [6261] = "Leve o Caixote de Larso para Dungar Tragolongo, o mestre de grifos.",
    [6281] = "Compre uma passagem de grifo do mestre de grifos Thor, e leve o Bilhete do Ludovico para Larso Norde na loja Imunidade Limitada, que fica na Cidade Velha, em Ventobravo.",
    [6282] = "Maggran Ata Terra, no Retiro Rocha do Sol, quer que você mate 7 Hapias Furissague, 7 Emboscadoras Furissangue, 7 Matadoras Furissangue e 7 Plumerrantes Furissangue.",
    [6283] = "Maggram, no Retiro Rocha do Sol, quer que você mate a Estripadora Furissangue e traga os restos mortais dela como prova de seu feito.",
    [6284] = "Mate Besseleth e leve a Presa de Besseleth a Maggran no Retiro Rocha do Sol.",
    [6285] = "Compre uma passagem para o Morro da Sentinela do mestre de grifos Dungar Tragolongo. Em seguida, leve o Caixote de Larso para Ludovico, no Morro da Sentinela.",
    [6301] = "Tammra Campo de Vento, no Retiro Rocha do Sol, quer que você colete 10 Sementes de Gaia.",
    [6321] = "Leve as Ordens do Rodrigo para Carlos Razok.",
    [6322] = "Leve o Caixote do Antônio até Miguel Garreta.",
    [6323] = "Adquira uma viagem de morcego até a Cidade Baixa com o tratador de morcegos Carlos Razok. Em seguida, leve as Ordens do Rodrigo para Antônio Nunes, na Cidade Baixa.",
    [6324] = "Adquira um voo de morcego para o Sepulcro do tratador de morcegos Miguel Garreta, depois entregue o Caixote do Antônio para o Necroguarda Rodrigo, no Sepulcro.",
    [6341] = "Leve a Coleção de Nessa para Vesprystus.",
    [6342] = "Viaje de hipogrifo para Auberdine com o mestre de hipogrifos Vesprystus, depois leve a Coleção de Nessa para Laird.",
    [6343] = "Leve a Resposta de Laird para Nessa Cantonegro.",
    [6344] = "Fale com Nessa Cantonegro.",
    [6361] = "Leve o Pacote de Peles para o mestre de mantícoras Devrak, na Encruzilhada.",
    [6362] = "Pegue uma mantícora com o mestre de mantícoras Devrak e leve o Pacote de Peles para Ahanu, no Penhasco do Trovão.",
    [6363] = "Leve os Artigos em Couro do Ahanu para Tal no Penhasco do Trovão.",
    [6364] = "Pegue uma mantícora para a Encruzilhada com o mestre de mantícoras Tal e leve os Artigos em Couro do Ahanu para Jahan Asa de Falcão.",
    [6365] = "Leve as Carnes de Zargh para Devrak, na Encruzilhada.",
    [6381] = "Plante 10 Sementes de Gaia em Montículos de Terra de Gaia e, então, devolva as Sementes Encantadas de Gaia restantes a Tammra, no Retiro Rocha do Sol.",
    [6382] = "Fale com Senani Coração Trovejante no Posto Machadada, que fica no Vale Gris.",
    [6384] = "Pegue uma mantícora para a Orgrimmar com o mestre de mantícoras Devrak, depois leve as Carnes de Zargh para Orgrimmar.",
    [6385] = "Entregue a Carta de Gryshka para Doraso em Orgrimmar.",
    [6386] = "Pegue uma mantícora para a Encruzilhada com o mestre de mantícoras Doraso e leve a Carta de Gryshka para Zargh, na Encruzilhada.",
    [6387] = "Leve a Lista de Brock para Thorgrum Borrelson, em Thelsamar.",
    [6388] = "Entregue as Picaretas Honorárias para Grif Trovino em Altaforja.",
    [6389] = "Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Nataniel Dumah, no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais.",
    [6390] = "Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Guel Levine, no Baluarte, que fica nas Clareiras de Tirisfal.",
    [6391] = "Compre um voo de grifo para Altaforja do mestre de grifos Thorgrum Borrelson. Chegando lá, entregue a Lista de Brock para Golnir Topadão.",
    [6392] = "Compre um voo de grifo para Thelsamar do mestre de grifos Grif Trovino. Chegando lá, entregue as Picaretas Honorárias para Brock Buscapedra.",
    [6393] = "Leve 10 Incenderitas a Tsunomem no Retiro Rocha do Sol.",
    [6394] = "Leve a Picareta de Thazz'ril para o Encarregado Thazz'ril.",
    [6395] = "Leve os Restos de Saulo Mitos para o Túmulo de Marla, depois fale novamente com a Noviça Elvira.",
    [6401] = "Conte a boa notícia a Tammra Campo de Vento no Retiro Rocha do Sol.",
    [6402] = "Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou.",
    [6403] = "Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!",
    [6421] = "Explore as profundezas da caverna na Ravina da Avalanche e colete 10 Cristais de Ressonita para que Mor'rogal, no Retiro Rocha do Sol, os analise.",
    [6441] = "Consiga 16 Chifres de Sátiro para Pixel no Posto Machadada.",
    [6442] = "Entregue 20 Cabeças de Iracauda a Marukai, na Praia de Zoram.",
    [6461] = "Xen'Zilla, em Malaka'Jin, precisa que você mate 10 Rastejadoras de Fundolimo e 7 Cospeçonhas de Fundolimo.",
    [6462] = "Entregue 8 Patuás Troll para Mitsuwa, no Assentamento Zoram'gar.",
    [6481] = "Abra o esquife de ressonita com o Cristal de Ressonita Encantado e, então, mate Goggeroc. Fale novamente com Mor'rogal levando as notícias e o Cristal de Ressonita Encantado.",
    [6482] = "Escolte Ruul e, em seguida, fale com Yama Casco de Neve, no Posto Machadada.",
    [6501] = "Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe.",
    [6502] = "Confronte o General Drakkisath e consiga o Sangue do Campeão dos Dragões Negros. Drakkisath está na sala do trono atrás dos Salões da Ascensão, no Pico da Rocha Negra.",
    [6503] = "Mate 9 Vanguardeiros do Vale Gris, depois fale novamente com Koray'bin, no Posto Machadada.",
    [6504] = "Encontre as 12 páginas que voaram do Manual de Operações do Retalhador e organize-as nos capítulos 1, 2 e 3. Devolva o manual a Gurda Marcafúria, que está perto do Posto Machadada.",
    [6521] = "Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa.",
    [6522] = "Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa.",
    [6523] = "Escolte Kaya Casco Chato até a Aldeia Apareje e, então, fale novamente com Makaba Casco Chato perto da extremidade sudeste das Torres de Pedra.",
    [6541] = "Apresente-se a Kadrak na torre de vigia dos Sertões Setentrionais.",
    [6542] = "Apresente-se a Kadrak na torre de vigia dos Sertões Setentrionais.",
    [6543] = "Abra o Monte de Relatórios e entregue os Relatórios dos Brado Guerreiro ao Batedor do Brado Guerreiro, o Mensageiro do Brado Guerreiro e o Pioneiro do Brado Guerreiro. Em seguida, entregue o informe sobre a situação atual que você receberá de cada um deles para Kadrak, na torre de vigia do norte dos Sertões.",
    [6544] = "Acompanhe Torek no ataque ao Posto Avançado Asa de Prata e sua comandante, Duriel Flameluna. Em seguida, apresente-se a Ertog Raivatusco no Posto Machadada.",
    [6548] = "Mate 8 Rufiões Temível Totem e 6 Mercenários Temível Totem para, então, voltar a falar com Makaba Casco Chato perto da extremidade sudoeste das Torres de Pedra.",
    [6561] = "Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão.",
    [6562] = "Fale com Je'neu Sancrea no Vale Gris.",
    [6563] = "Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris.",
    [6564] = "Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris.",
    [6565] = "Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris.",
    [6566] = "Ouça Thrall.",
    [6567] = "Procure Rexxar. O Chefe Guerreiro <o/a> instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas.",
    [6568] = "Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais.",
    [6569] = "Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa.",
    [6570] = "Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta.",
    [6571] = "Colete os seguintes Suprimentos do Brado Guerreiro: Lâminas Serrilhadas dos Brado Guerreiro, Corda para Transportar Toras, Óleo dos Brado Guerreiro e Carregamento de Machados dos Brado Guerreiro para Locke Okarr no Posto Machadada.",
    [6582] = "Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta. Você sabe que o Áugure se encontra em Hibérnia.",
    [6583] = "Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta.",
    [6584] = "Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta.",
    [6585] = "Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta.",
    [6601] = "Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer.",
    [6602] = "Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar.",
    [6603] = "Encontre Bruna Covaneve perto das fontes termais de Hibérnia.",
    [6604] = "Fale com Jaron Moldapedra na Aldeia Chuva Estelar.",
    [6605] = "Fale com Winna Perícon na Selva Maleva.",
    [6607] = "Nat Pagle quer que você pesque os seguintes peixes: O Graçapé-brumalga, na Praia Brumalga, que fica no Pântano das Mágoas. A Piranha-de-sar'theris, na Praia de Sar'theris, que fica na Desolação. O Atum-amarelo-de-feralas, no Rio Verdantis, em Feralas. A Molinésia-azul-da-costa-selvagem, na Costa Selvagem, na Selva do Espinhaço. Fale novamente com Nat Pagle quando já tiver fisgado todos!",
    [6608] = "Você acha que Lumak está tentando dizer que ele já não pode mais ajudar a melhorar suas habilidades de pesca. Você pode tentar encontrar o amigo dele, Nat Pagle, um humano pescador, que fica em uma das ilhas ao sul de Theramore (pelo menos é isso o que você acha que Lumak disse).",
    [6609] = "Vá até a cidade costeira de Theramore, em Kalimdor. A partir de lá, procure uma ilha a sul da capital. Nat Pagle <o/a> aguarda!",
    [6610] = "Funesto Marrão quer que você consiga os seguintes itens: 12 Ovos Gigantescos. Você os encontra nas rocas que vagueiam por Tanaris ou em qualquer pássaro grande. 10 fatias de Carne de Marisco Condimentada. Você as encontra dentro dos mariscos, óbvio! 20 pedaços de Queijo Furado de Alterac. Procure alguém que venda esse queijo! Consiga todos os itens e fale novamente com Funesto.",
    [6611] = "Vá para Geringontzan, no Deserto de Tanaris, e fale com Funesto Marrão para progredir na carreira de cozinheiro.",
    [6612] = "Vá para Geringontzan, no deserto de Tanaris, e fale com Funesto Marrão sobre como se desenvolver na carreira de <cozinheiro/cozinheira>.",
    [6621] = "Finque o Estandarte de Karang no Montículo Totêmico dos Torpeflora. Não deixe que os pelursos destruam o estandarte. Derrote o Chefe Murgut e leve o Totem de Murgut para Karang Amakkar em Zoram'gar.",
    [6622] = "Use Bandagens de Triagem para salvar pacientes. Você precisa salvar 15 deles antes que 6 morram devido aos ferimentos. Lembre-se da ordem da triagem! Os Soldados Mortalmente Feridos são os que morrem mais rápido, seguidos dos Soldados Gravemente Feridos. Os Soldados Feridos demoram mais a morrer e devem ser tratados após os outros terem passado pela triagem.",
    [6623] = "Vá para a Ruína do Martelo no Planalto Arathi e fale com o Doutor Victor Zerbini para entrar para a equipe do Pronto-socorro da Horda.",
    [6624] = "Use Bandagens de Triagem para salvar pacientes. Você precisa salvar 15 deles antes que 6 morram devido aos ferimentos. Lembre-se da ordem da triagem! Os Soldados Mortalmente Feridos são os que morrem mais rápido, seguidos dos Soldados Gravemente Feridos. Os Soldados Feridos demoram mais a morrer e devem ser tratados após os outros terem passado pela triagem.",
    [6625] = "Vá para a cidade de Theramore, no Pântano Vadeoso, e fale com o Doutor Gregório Casagrande sobre entrar para a equipe do Pronto-socorro da Aliança.",
    [6626] = "Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos.",
    [6627] = "Responda à pergunta de Braug Espírito Turvo corretamente, depois fale com ele novamente. Quando você estiver pronto, ele estará na Cordilheira das Torres de Pedra.",
    [6628] = "Responda à pergunta de Pasqual Fintallas corretamente, depois fale com ele novamente. Quando você estiver pronto, ele estará na Cidade Baixa.",
    [6629] = "Mate Grundig Nuvem Negra e 6 Brutos Temível Totem, e fale novamente com Makaba Casco Chato perto da extremidade sudeste das Torres de Pedra.",
    [6641] = "Escolte Muglash em segurança até o braseiro. Ajude-o a apagar o braseiro, e proteja-o na luta contra as nagas. Se cumprir a missão, volte ao Assentamento Zoram'gar e informe o Mensageiro do Brado Guerreiro da morte de Vorsha, a Açoitadora.",
    [6661] = "Capture 5 Ratos Correfundo com a Flauta do Pegador de Ratos. Conduza os ratos até o Monty. Não se esqueça de entregar a flauta quando terminar.",
    [6662] = "Entregue a Caixa de Carne Duvidosa para Nipsy, na estação do Metrô Correfundo de Ventobravo.",
    [6681] = "Leve o Selo de Corvoforte para Fahrad na Mansão de Corvoforte, que fica oculta nas colinas de Eira dos Montes. Sua jornada testará sua sagacidade. Prepare-se.",
    [6721] = "Fale com Dazalar em Dolanaar.",
    [6722] = "Fale com Dazalar em Dolanaar.",
    [6761] = "Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano, em Darnassus.",
    [6762] = "Fale com Ravine Saturna no Refúgio Noturno, que fica na Clareira da Lua. A Clareira da Lua fica entre a Selva Maleva e Hibérnia. Uma estrada que sai do Domínio dos Presamatos leva até lá.",
    [6804] = "Use o Aspecto de Neptulon nos elementais contaminados das Terras Pestilentas Orientais. Leve 12 Braçadeiras Dissonantes e o Aspecto de Neptulon ao Duque Hidráxis em Azshara.",
    [6805] = "Mate 15 Tempestades de Poeira e 15 Estrondores do Deserto e fale novamente com o Duque Hidráxis em Azshara.",
    [6821] = "Leve o Olho do Mirabrasa ao Duque Hidráxis em Azshara.",
    [6822] = "Mate 1 Senhor do Fogo, 1 Gigante Derretido, 1 Cão-magma Antigo e 1 Irrompedor de Lava e depois fale novamente com o Duque Hidráxis em Azshara.",
    [6823] = "Alcance a reputação de <Honrado/Honrada> pelos Senhores das Águas Hidraxianos e depois fale com o Duque Hidráxis em Azshara.",
    [6824] = "Leve as Mãos de Lúcifron, Sulfuron, Geena e Shazzrah ao Duque Hidráxis em Azshara.",
    [6844] = "Leve o Objeto Silitídeo Incrustado para Umbero, arquivista do Círculo Cenariano, na vila de Refúgio Noturno, na Clareira da Lua.",
    [6845] = "Fale com Ravine Saturna no vilarejo de Refúgio Noturno, na Clareira da Lua.",
    [6921] = "Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.",
    [6922] = "Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris.",
    [6981] = "Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante. Depois, entregue a lasca conforme as orientações.",
    [6982] = "Leve 10 Suprimentos dos Dentefrio para o Intendente da Aliança em Dun Baldar.",
    [6985] = "Leve 10 Suprimentos dos Ferrofundo para o Intendente da Horda na Bastilha Lobo do Gelo.",
    [7001] = "Localize um Lobo do Gelo no Vale Alterac. Use a Focinheira de Lobo do Gelo para \"domar\" a fera. Uma vez domado, o Lobo do Gelo seguirá você até o Mestre dos Estábulos dos Lobo do Gelo. Fale com o Mestre dos Estábulos para conseguir crédito pela captura.",
    [7003] = "Use o Ultra-encolhedor de Zorbin para deixar qualquer tipo de gigante de Feralas com um tamanho mais compacto e manejável. Colete 15 Resíduos de Miniaturização encontrados nos gigantes encolhidos e leve a Zorbin Cegasvista nas docas da Costa Esquecida, em Feralas.",
    [7027] = "Localize um Carneiro de Alterac, no Vale Alterac. Use a Coleira de Treinamento de Lançatroz no Carneiro de Alterac para \"domar\" a fera. Uma vez domado, o Carneiro de Alterac seguirá você até o Mestre dos Estábulos. Fale com o Mestre dos Estábulos para conseguir crédito pela captura.",
    [7028] = "Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação.",
    [7029] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra.",
    [7041] = "Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel.",
    [7044] = "Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras. Encontre um jeito de falar com Celebras.",
    [7046] = "Ajude Celebras, o Redimido, a criar o Cetro de Celebras. Fale com ele quando o ritual estiver concluído.",
    [7064] = "Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação.",
    [7065] = "Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação.",
    [7066] = "Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida.",
    [7067] = "Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação.",
    [7068] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar.",
    [7070] = "Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso.",
    [7081] = "Ataque um cemitério e, então, apresente-se ao Sargento Durgen Lançatroz nas Montanhas de Alterac.",
    [7082] = "Ataque um cemitério e depois apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac.",
    [7101] = "Capture uma casamata inimiga e então apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac.",
    [7102] = "Destrua o estandarte em uma torre ou casamata inimiga, e então fale novamente com o Sargento Durgen Lançatroz nas Montanhas de Alterac.",
    [7121] = "Fale com o Intendente dos Lançatroz.",
    [7122] = "Capture uma mina não controlada pelos Lançatroz e, a seguir, apresente-se ao Sargento Durgen Lançatroz nas Montanhas de Alterac.",
    [7123] = "Fale com o Intendente dos Lobo do Gelo.",
    [7124] = "Capture uma mina e, a seguir, apresente-se à Cabo Tika Rosnassangue nas Montanhas de Alterac.",
    [7141] = "Siga para o Vale Alterac, derrote Drek'thar, o general da Horda, e volte a falar com o Prospector Entalharrocha nas Montanhas de Alterac.",
    [7142] = "Siga para o Vale Alterac, derrote Vanndar Lançatroz, o general anão, e fale novamente com Voggah Garramort, nas Montanhas de Alterac.",
    [7161] = "Vá até a caverna dos Garragreste, a sudeste da base principal no Vale Alterac, e encontre o Estandarte dos Lobo do Gelo. Entregue o Estandarte dos Lobo do Gelo para o Mestre Guerreiro Laggrond.",
    [7162] = "Viaje para a Caverna Asálgida a sudoeste de Dun Baldar, no Vale Alterac, e recupere o Estandarte dos Lançatroz. Entregue o Estandarte dos Lançatroz para o Tenente Haggerdin nas Montanhas de Alterac.",
    [7181] = "De acordo com a lenda, o líder dos poderosos trolls Invernacha aparece esporadicamente para trazer destruição e caos aos moradores do Vale Alterac. Se Korrak aparecer, destrua-o e fale novamente com o Mestre Guerreiro Laggrond.",
    [7201] = "Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais.",
    [7202] = "De acordo com a lenda, o líder dos poderosos trolls Invernacha aparece quando bem entende para trazer destruição e caos aos moradores do Vale Alterac. Se Korrak aparecer, mate-o e fale novamente com o Tenente Haggerdin nas Montanhas de Alterac.",
    [7223] = "Leve 20 Sobras de Armadura para Murgot Baixaforja em Dun Baldar.",
    [7224] = "Leve 20 Sobras de Armadura para o Ferreiro Regzar na Aldeia Lobo do Gelo.",
    [7241] = "Explore o Vale Alterac, localizado nas Montanhas de Alterac. Encontre o Mestre Guerreiro Laggrond, que fica diante da entrada do túnel, e converse com ele para começar a sua carreira de soldad<o/a> Lobo do Gelo. O Vale Alterac fica ao norte da Serraria Tarren, no sopé das Montanhas de Alterac.",
    [7261] = "Vá ao Vale Alterac no Contraforte de Eira dos Montes. Encontre e fale com o Tenente Haggerdin em frente ao túnel de entrada. Pela glória de Barbabronze!",
    [7281] = "Siga para o território dos Lançatroz e mate o Comandante Carlos Filipe. Em seguida, fale novamente com o Comandante Luis Filipe.",
    [7282] = "Siga para o território dos Lobo do Gelo e mate o Comandante Luis Filipe. Fale novamente com o Comandante Carlos Filipe quando a missão for completada.",
    [7301] = "Siga para o território dos Lobo do Gelo e procure pelo Comandante de Ala Slidore, Comandante de Ala Vipore e Comandante de Ala Ichman. Fale novamente com o Comandante Duffy ao completar a missão.",
    [7302] = "Descubra o que houve com o Comandante de Ala Guze, o Comandante de Ala Jeztor e o Comandante de Ala Mulverick. Fale novamente com o Comandante Mulfort ao completar a missão.",
    [7321] = "Leve 10 pedaços de Carne de Tartaruga e alguns Temperos Reconfortantes para Cristóvão Casaqueiro, na Serraria Tarren.",
    [7361] = "Você recebeu a missão de matar jogadores elfos noturnos inimigos no Vale Alterac. Mate um elfo noturno e leve uma Cabeça Decepada de Elfo Noturno para Najak Bagatão na Bastilha Lobo do Gelo.",
    [7362] = "Você recebeu a missão de matar jogadores gnomos inimigos no Vale Alterac. Mate um gnomo e leve um Tufo de Cabelo de Gnomo para Ravak Temível Totem na Bastilha Lobo do Gelo.",
    [7363] = "Você recebeu a missão de matar jogadores humanos inimigos no Vale Alterac. Mate um humano e leve uma Lasca de Osso Humano para o Comandante Luis Filipe (que fica entre a linha de frente e a Bastilha Lobo do Gelo). A cura para a condição humana está próxima!",
    [7366] = "Você recebeu a missão de matar jogadores Renegados inimigos no Vale Alterac. Mate um Renegado e leve um Coração de Renegado para o Comandante Carlos Filipe (que fica entre a serraria e a mina).",
    [7381] = "Se Korrak, o Sanguinário, voltar ao Campo de Disputa, procure-o e destrua-o. Leve o Crânio de Korrak para o Mestre Guerreiro Laggrond no Contraforte de Eira dos Montes.",
    [7382] = "Se Korrak, o Sanguinário, voltar ao Campo de Disputa, encontre-o e destrua-o. Entregue o Crânio de Korrak para o Tenente Haggerdin no Contraforte de Eira dos Montes.",
    [7383] = "Encha o Frasco de Ametista e leve-o de volta para Corithras Lunafúria em Dolanaar.",
    [7441] = "Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin. Fale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos.",
    [7461] = "Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará. Destrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu. Fale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão.",
    [7463] = "Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu.",
    [7481] = "Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar.",
    [7482] = "Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar.",
    [7483] = "Leve 1 Incunábulo de Rapidez, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes, e 2 Sangues dos Heróis ao Erudito Lydros no Gládio Cruel para receber um Arcano de Rapidez.",
    [7484] = "Leve 1 Incunábulo de Concentração, 1 Diamante Preto Límpido, 4 Estilhaços Brilhantes Grandes, e 2 Peles de Sombra ao Erudito Lydros no Gládio Cruel para receber um Arcano de Concentração.",
    [7485] = "Leve 1 Incunábulo de Proteção, 1 Diamante Preto Límpido, 2 Estilhaços Brilhantes Grandes e 1 Sutura de Abominação Puída ao Erudito Lydros no Gládio Cruel para receber um Arcano de Proteção.",
    [7486] = "Obtenha a recompensa na Arca de Hidráxis.",
    [7488] = "Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas.",
    [7489] = "Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas.",
    [7490] = "Leve a Cabeça da Onyxia para Thrall em Orgrimmar.",
    [7491] = "Procure o Lorde Supremo Runthak no Vale da Força.",
    [7492] = "Fale com Talo Casco de Espinhos na Aldeia Mojache, em Feralas.",
    [7494] = "Fale com Latrônicus Lunalança no Domínio de Plumaluna, em Feralas.",
    [7495] = "Leve a Cabeça da Onyxia ao Grão-lorde Bolvar Fordragon em Ventobravo.",
    [7496] = "Procure o Major Valadão no Vale dos Heróis.",
    [7498] = "Devolva o livro aos legítimos donos.",
    [7499] = "Devolva o livro aos legítimos donos.",
    [7500] = "Devolva o livro aos legítimos donos.",
    [7501] = "Devolva o livro aos legítimos donos.",
    [7502] = "Devolva o livro aos legítimos donos.",
    [7503] = "Devolva o livro aos legítimos donos.",
    [7504] = "Devolva o livro aos legítimos donos.",
    [7505] = "Devolva o livro aos legítimos donos.",
    [7506] = "Devolva o livro aos legítimos donos.",
    [7507] = "Leve o Compêndio do Abate de Dragões de Nostro até o Ateneu.",
    [7508] = "Dê a Lâmina Élfica Lisa e Cega ao Erudito Lydros.",
    [7509] = "Faça Onyxia soprar fogo na Lâmina Ancestral Virgem. Quando conseguir, pegue a agora Lâmina Ancestral Incandescente. Atenção, uma Lâmina Ancestral Incandescente não permanecerá assim para sempre — o tempo urge. O último passo antes de voltar para mim é matar a fera e enfiar a Lâmina Ancestral Incandescente no cadáver dela. Faça isso e Quel'Serrar será sua.",
    [7562] = "Fale com Mor'zul Trazangre nas Estepes Ardentes.",
    [7563] = "Leve 30 garrafas de Sangue de Fera em Fúria para Mor'zul Trazangre nas Estepes Ardentes.",
    [7564] = "Leve o Caixote de Sangue para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7581] = "Vá até o Gládio Cruel, em Feralas, e obtenha 15 amostras de Sangue de Sátiro dos Sátiros Criasselvagem que habitam o Distrito Lenhatorta. Fale novamente com Daio no Rasgo Infecto quando tiver feito isso.",
    [7582] = "Vá à Garganta do Sussurro Sombrio em Hibérnia e recupere 5 Lágrimas dos Hederine dos demônios Hederine que ocupam o lugar. Fale novamente com Daio no Rasgo Infecto quando você tiver completado esta tarefa.",
    [7583] = "Aventure-se no Rasgo Infecto e encontre um Comandante Demonarca. Use a Prisão de Cristal Faiscante no Comandante Demonarca. Prepare-se para uma sequência violenta de ataques, enquanto o demônio tenta escapar de ser preso. Caso você tenha sucesso, leve o Demonarca Aprisionado para Daio no Rasgo Infecto.",
    [7601] = "Fale com Diabretim na Selva Maleva.",
    [7602] = "Leve três Essências Vis Impecáveis, originárias de três locais distintos, para Diabretim na Selva Maleva. Os Sátiros Legashi de Azshara possuem a Essência Vil Impecável da região deles, assim como os Legionários de Jaedenar e as Sentinelas Guardas Vis da Barreira do Inferno. Busque as Essências Vis Impecáveis e leve-as para Diabretim, na Selva Maleva.",
    [7603] = "Procure os restos mortais de Kroshius no Vale das Escaras Pungentes, que fica na Selva Maleva. Ao encontrá-los, use o Fogo Vil perto deles e aguarde o retorno de Kroshius. Quando o infernal acordar, mate-o e retire do corpo dele o Núcleo Infernal de Kroshius. Leve o Núcleo para Niby, o Todo-poderoso na Selva Maleva.",
    [7604] = "Entregue o Contrato da Irmandade do Tório para Lokhtos Umbrarganha, caso tenha interesse em receber as instruções para Sulfuron.",
    [7622] = "Salve 50 Camponeses antes que 15 sejam mortos. Fale com Eris Abrigoardente se conseguir completar a tarefa. Você pode conferir o Poste da Morte para saber quantos Camponeses foram mortos.",
    [7623] = "Compre Poções Sombrias de Gorzeeki nas Estepes Ardentes. Use as poções para viajar através de Jaedenar e fale com Lorde Nihilus.",
    [7624] = "Confronte Ulathek, depois leve o Coração do Traidor para o Lorde Nihilus em Jaedenar.",
    [7625] = "Compre Poeira Estelar Zorothiana de Ur'dan. Leve-a para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7626] = "Leve 10 Elixires de Poder Sombrio para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7627] = "Leve 6 Estilhaços Brilhantes Grandes e 25 Minérios de Ferro Negro para Gorzeeki nas Estepes Ardentes.",
    [7628] = "Leve 35 Escamas de Dragão Negro para Gorzeeki Olholouco nas Estepes Ardentes.",
    [7629] = "Leve o Diabrete numa Jarra para o laboratório de alquimia em Scolomântia. Depois que o pergaminho for criado, devolva a jarra para Gorzeeki Olholouco.",
    [7630] = "Leve 3 Barras de Arcanita para Gorzeeki nas Estepes Ardentes.",
    [7631] = "Leia as Instruções de Mor'zul. Evoque um Corcel Medonho Zorothiano, derrote-o e então vincule o espírito dele a você.",
    [7632] = "Encontre o dono da Folha Antiga Petrificada. Boa sorte, <name>, pois o mundo é grande.",
    [7634] = "Hastat, o Anciente, lhe pediu um Tendão de Dragão Azul Maduro. Se você encontrar esse tendão, vá falar com Hastat na Selva Maleva.",
    [7635] = "Stoma, o Anciente, lhe pediu um Tendão de Dragão Negro Maduro. Se você encontrar esse tendão, vá falar com Stoma na Selva Maleva.",
    [7636] = "Você precisa encontrar e destruir aqueles quatro corruptores demoníacos: Simone, a Sedutora. Klinfran, o Enlouquecido. Solenor, o Matador. Artórius, o Destruidor. Destrua aquelas criaturas e fale novamente com Vartrus, o Anciente, na Selva Maleva, trazendo as cabeças deles. Consulte a Casca Petrificada no seu inventário para ter pistas da localização deles. Você TEM QUE completar a tarefa sozinh<o/a>.",
    [7637] = "Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo.",
    [7638] = "Fale com o Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7639] = "Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7640] = "Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7641] = "Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo.",
    [7642] = "Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo.",
    [7643] = "Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração. Entre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe.",
    [7644] = "Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7645] = "Obtenha 20 Biscoitos de Maná Enriquecido — o ingrediente chave para fazer Ração de Cavalo Enriquecida com Mana — para Judite Castanheira da Costa Sul, no Contraforte de Eira dos Montes. A Aurora Argêntea é conhecida como a única fornecedora dos biscoitos. Você também precisa dar a ela 50 moedas de ouro para a apaziguar os ânimos dela.",
    [7646] = "Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7647] = "Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído. Entregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus.",
    [7648] = "Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione.",
    [7649] = "Devolva o livro aos legítimos donos.",
    [7650] = "Devolva o livro aos legítimos donos.",
    [7651] = "Devolva o livro aos legítimos donos.",
    [7667] = "Se você tiver interesse em ajudar Sagorne Monta Crista, no Vale da Sabedoria de Orgrimmar, leve para ele um Diamante Azerotiano e um Diamante Preto Límpido.",
    [7670] = "Fale com o Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo.",
    [7701] = "Nas profundezas do Fosso de Lava do Caldeirão, na Garganta Abrasadora, você encontrará o anão traidor dos Ferro Negro chamado Feitor Maltorius. Mate o Feitor Maltorius, arranque a cabeça dele e leve-a para o Capitão-vigia Lolo Longalcance na Garganta Abrasadora para receber sua recompensa.",
    [7703] = "Encontre as Manoplas do Poder de Gordok e devolva-as para o Capitão Kebrapaw no Gládio Cruel. De acordo com Kebrapaw, a \"história de ancião\" diz que Tortheldrin — um elfo \"medonho\" que se diz príncipe — roubou as manoplas de um dos reis Gordok.",
    [7721] = "Colete 10 Âmagos dos Elementais de Água dos Elementais do Mar e dos Borrifos do Mar ao longo da Costa Esquecida de Feralas, e leve-os para Zorbin Cegasvista, próximo às docas.",
    [7722] = "Em algum lugar do Fosso de Lava do Caldeirão você encontra as Instruções Secretas: Fluxo Ígneo que o Feitor Maltorius roubou. Encontre as instruções e devolva-as ao Mestre Ferreiro Queimatar na Garganta Abrasadora.",
    [7723] = "Hansel Mão-pesada quer que você mate 20 Golens de Guerra Pesados. Os Golens de Guerra Pesados perambulam pelas áreas em torno do Caldeirão, na Garganta Abrasadora. Quando tiver matado a quantidade necessária, fale novamente com Hansel na Garganta Abrasadora.",
    [7724] = "Hansel Mão-pesada quer que você mate 20 Grandes Aranhas de Lava na Garganta Abrasadora. Você pode encontrá-las nos platôs e poços de lava do local. Depois de matar as Grandes Aranhas de Lava, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.",
    [7725] = "Use o Ultra-encolhedor de Zorbin para deixar qualquer tipo de gigante de Feralas com um tamanho mais compacto e manejável. Colete 10 Resíduos de Miniaturização encontrados nos gigantes encolhidos e leve para Zorbin Cegasvista, que fica nas docas da Costa Esquecida, em Feralas.",
    [7726] = "Colete 6 Âmagos dos Elementais de Água dos Elementais do Mar e dos Borrifos do Mar ao longo da Costa Esquecida de Feralas e leve-os para Zorbin Cegasvista, próximo às docas.",
    [7727] = "Hansel Mão-pesada quer que você mate 20 Incendossauros. Eles ocupam as poças dentro do Fosso de Lava. O Fosso de Lava fica no Caldeirão da Garganta Abrasadora. Depois de matar os Incendossauros, fale novamente com Hansel Mão-pesada na Garganta Abrasadora.",
    [7728] = "Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora. A única informação que você tem sobre esses itens é a seguinte: com certeza foram roubados por anões Ferro Negro. O Alcaraviz de Ferraria é uma ferramenta usada por ferreiros e a Luneta do Espia é um aparelho de monitoramento inestimável para vigias.",
    [7729] = "Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora.",
    [7730] = "Traga 20 Carapaças de Zukk'ash para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas.",
    [7731] = "Derrote Cravaçoite na Profundeza Atormentada, leve as glândulas para Hadoken Passo Veloz na Aldeia Mojache, que fica em Feralas.",
    [7732] = "Entregue o Relatório sobre Zukk'ash da Aldeia Mojache para Zilzibin Tamborleiro. Ele fica no Bazar de Orgrimmar.",
    [7733] = "Leve 10 Pelegos de Yeti Cortifúria para Pradal McGrubben no Domínio de Plumaluna, em Feralas.",
    [7734] = "Leve 10 Pelegos de Yeti Cortifúria para Jangdor Passo Veloz na Aldeia Mojache, em Feralas.",
    [7735] = "Leve o Pelego Imaculado de Yeti para Pradal McGrubben no Domínio de Plumaluna, em Feralas.",
    [7738] = "Leve o Pelego Perfeito de Yeti para Jangdor Passo Veloz na Aldeia Mojache, que fica em Feralas.",
    [7761] = "Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath. A carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar.",
    [7781] = "Leve a Cabeça de Nefarian para o Grão-lorde Bolvar Fordragon, em Ventobravo.",
    [7782] = "Vá até o Vale dos Heróis, em Ventobravo, e fale com o Marechal de Campo Afrasiabi.",
    [7783] = "Leve a Cabeça de Nefarian para Thrall, em Orgrimmar.",
    [7784] = "Fale com o Lorde Supremo Saurfang em Orgrimmar. Ele espera por você no Vale da Força.",
    [7785] = "Examine o Casulo de Renascimento e entregue-o para o Grão-lorde Dimitriano.",
    [7786] = "Para libertar Trovejardus, o Perseguidor dos Ventos, de sua prisão, você deve entregar as metades direita e esquerda dos Grilhões do Perseguidor dos Ventos, 10 Barras de Elemêntio Encantadas e a Essência do Senhor do Fogo para o Grão-lorde Dimitriano em Silithus.",
    [7787] = "Entregue a Lâmina Latente Beijada pelo Vento para o Grão-lorde Dimitriano.",
    [7810] = "Fale com João Tampinha Mithril na Arena da Selva do Espinhaço.",
    [7815] = "Katum, o Pesqueiro, quer que você mate 15 tartarugas Mordeliscas de Água Salgada. Fale novamente com ele na Aldeia Revatusco, que fica nas Terras Agrestes, quando concluir a tarefa.",
    [7816] = "Katum, o Pesqueiro, na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate Gammerita e apanhe a Melhor Isca de Katum da carcaça. Katum mencionou que Gammerita circula pela costa com as outras tartarugas.",
    [7828] = "O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 15 Espreitadores Jubaprata e 15 Uivadores Jubaprata. Ao terminar a tarefa, fale novamente com ele. Markhor mencionou que os lobos se escondem na selva das Terras Agrestes.",
    [7829] = "O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 20 Ferujas Selvagens. Ao terminar a tarefa, fale novamente com ele. Markhor mencionou que as Ferujas Selvagens dominam a selva nas Terras Agrestes.",
    [7830] = "O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate um Senhor Celeste Bicavalha e tire dele a Pluma de Senhor Celeste. Ao terminar a tarefa, fale novamente com Markhor. Ele mencionou que os Senhores Celestes Bicavalha são uma espécie rara que ocupa a selva nas Terras Agrestes.",
    [7839] = "O Ferreiro Escoriárvore, da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre as Ferramentas Perdidas de Escoriárvore. Quando terminar, fale novamente com ele. Você lembra que Escoriárvore mencionou que as ferramentas podem estar em um dos templos Ramatorpe no nordeste das Terras Agrestes. É bom procurar também em Rocha Oculta.",
    [7840] = "Banha na Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre o Almoço do Banha. Fale novamente com ele quando a tarefa for concluída. Banha mencionou tê-lo esquecido na ilha ao norte. Cuidado com os trolls Ramatorpe.",
    [7841] = "Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 15 Vanguardeiros do Altovale, 15 Batedores de Altovale, 15 Atiradores Peritos do Altovale e 15 Patrulheiros do Altovale. Quando terminar, fale novamente com ele. Você encontra os elfos superiores de Altovale no Pavilhão Quel'Danil, na região noroeste das Terras Agrestes.",
    [7842] = "Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você leve para ele 10 Penas Longas Elegantes extraídas dos grifos que habitam as Terras Agrestes. Quando terminar, fale novamente com ele. Grifos podem ser encontradas em todas as regiões das Terras Agrestes.",
    [7843] = "Joho'sér Mujik'ka da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você viaje para o Ninho da Águia, na região oeste das Terras Agrestes, e deixe a Mensagem Final para os Martelo Feroz ao lado do poço no centro da cidade. Quando terminar, fale novamente com ele. Cuidado com anões Martelo Feroz furiosos e com membros irritados da Aliança.",
    [7844] = "A Mística Yayo'jin da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você mate 30 Escalpeladores Ramatorpe e 15 Adivinhos Ramatorpe. Quando terminar, fale novamente com ela. Yayo'jin disse que você encontrará esses trolls perto dos templos de Shaol'watha e Agol'watha, região norte-nordeste das Terras Agrestes.",
    [7845] = "Primeva Presa-arrancada, da Aldeia Revatusco nas Terras Agrestes, quer que você resgate o companheiro dela, Ancião Presa-arrancada, que está em Jintha'Alor. Dizem que ele está preso no alto de Jintha'Alor, a capital dos Ramatorpe que fica na região sul das Terras Agrestes.",
    [7846] = "O Ancião Presa-arrancada, em Jintha'Alor, quer que você mate Hitah'ya, a Guardiã e pegue a Chave dos Grilhões para soltá-lo. Quando tiver a chave, fale novamente com o Ancião Presa-arrancada.",
    [7847] = "O Ancião Presa-arrancada, em Jintha'Alor, quer que você fale com Primeva Presa-arrancada, na Aldeia Revatusco, e avise que ele foi resgatado.",
    [7848] = "Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo.",
    [7849] = "O Guarda-caça Markhor da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre os restos mortais do irmão gêmeo dele. Encontre o Crânio do Guarda-caça Malkhor e os Ossos do Guarda-caça Malkhor e leve-os para o Guarda-caça Markhor. Markhor mencionou que os restos mortais foram deixados para os lobos e as gosmas dos Ramatorpe. Também disse que tem um fosso cheio de gosmas em Jintha'Alor, assim como um covil de lobos. Ambos lugares ficam perto do topo do templo.",
    [7850] = "Primeva Presa-arrancada da Aldeia Revatusco, que fica nas Terras Agrestes, quer que você encontre 10 Recipientes com Sangue Maculado em Jintha'Alor. Quando terminar, fale novamente com Primeva Presa-arrancada.",
    [7861] = "Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes. Você pode encontrar a Sacerdotisa Torpe Bagata e os Guardas Aman'zasi no alto de Jintha'Alor, nas Terras Agrestes.",
    [7862] = "Você recebeu a missão de dizimar 20 Berserkers Ramatorpe, 20 Caçadores Sombrios Ramatorpe, 20 Bebe-sangue Ramatorpe e 20 Devoradores de Almas Ramatorpe. Caso conclua a missão, fale com Primeva Presa-arrancada na Aldeia Revatusco, que fica nas Terras Agrestes.",
    [7877] = "Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Resgate sua recompensa!",
    [7907] = "Devolva o Baralho de Feras à Feira de Negraluna quando ela voltar à cidade.",
    [7927] = "Devolva o Baralho de Portais à Feira de Negraluna quando ela voltar à cidade.",
    [7928] = "Devolva o Baralho de Generais à Feira de Negraluna quando ela voltar à cidade.",
    [7929] = "Devolva o Baralho de Elementais à Feira de Negraluna quando ela voltar à cidade.",
    [8053] = "Leve as Braçadeiras Hakkari Primevas a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar.",
    [8054] = "Leve um Xale Hakkari Primevo a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Honrado/Honrada> pela Tribo Zandalar.",
    [8055] = "Leve um Tabardo Hakkari Primevo a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Reverenciado/Reverenciada> pela Tribo Zandalar.",
    [8056] = "Leve uma Tala Hakkari Primeva a Maywiki de Zuldazar, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar.",
    [8057] = "Leve um Pilar Hakkari Primevo a Maywiki de Zuldazar, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar.",
    [8058] = "Leve uma Tala Hakkari Primeva a Jin'rokh, o Rebentador. Sua reputação com a Tribo Zandalar precisa ser igual ou superior a <Amistoso/Amistosa>. Jin'rokh, o Rebentador, se encontra na Ilha Yojamba, que fica na Selva do Espinhaço.",
    [8059] = "Leve um Pilar Hakkari Primevo a Al'tabim, que Tudo Vê. Sua reputação com a Tribo Zandalar precisa ser igual ou superior a <Amistoso/Amistosa>. Al'tabim, que Tudo Vê, se encontra na Ilha Yojamba, que fica na Selva do Espinhaço.",
    [8060] = "Leve as Braçadeiras Hakkari Primevas a Al'tabim, que Tudo Vê, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar.",
    [8061] = "Leve um Pilar Hakkari Primevo a Al'tabim, que Tudo Vê, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar.",
