    [8728] = "Narain Suavestilo, em Tanaris, quer que você leve para ele 20 Barras de Arcanita, 10 Minérios de Elemêntio, 10 Diamantes Azerotianos e 10 Safiras Azuis.",
    [8729] = "Use a Boia de Arcanita na Voragem Serpenteante da Baía das Tempestades, que fica em Azshara.",
    [8730] = "Mate Nefarian e recupere o Estilhaço de Cetro Vermelho. Devolva o Estilhaço de Cetro Vermelho a Anacronos nas Cavernas do Tempo, em Tanaris. Você tem 5 horas para concluir a tarefa.",
    [8731] = "Apresente-se para Krug Rachacrânio no posto da Legião de Orgrimmar em frente a Colme'Régia. Prepare seus Papéis em Branco de Serviço em Campanha, obtenha Papéis Assinados de Serviço em Campanha e leve-os ao Arauto do Vento Kaldon no Forte Cenariano. Nota: curar ou lançar feitiços benéficos em um membro da Legião de Orgrimmar marcará você para o JxJ.",
    [8733] = "Vá para o continente de Teldrassil e encontre o agente de Malfurion perto das muralhas de Darnassus.",
    [8734] = "Vá à Clareira da Lua e fale com o Guardião Remulos.",
    [8735] = "Vá até os quatro portais do Sonho Esmeralda em Azeroth e obtenha um Fragmento da Corrupção do Pesadelo de cada um. Quando tiver cumprido essa tarefa, fale novamente com o Guardião Remulos na Clareira da Lua.",
    [8736] = "Defenda o Refúgio Noturno de Erânicos. Impeça que o Guardião Remulos pereça. Não mate Erânicos. Defenda-se. Espere Tyrande.",
    [8738] = "Contate o Batedor Cenariano Landion no interior da Colme'Régia e entregue o Relatório do Batedor de Colme'Régia ao Arauto do Vento Chifre Altivo no Forte Cenariano. Você também precisa entregar as Instruções Táticas VII para concluir a missão.",
    [8739] = "Contate a Batedora Cenariana Jalia no interior da Colme'Ashi e entregue o Relatório do Batedor de Colme'Ashi ao Arauto do Vento Chifre Altivo no Forte Cenariano. Você também precisa entregar as Instruções Táticas VIII para concluir a missão.",
    [8740] = "Mate a Espoliadora do Crepúsculo Mirna e 5 Espoliadores do Crepúsculo. Apresente-se ao Arauto do Vento Chifre Altivo depois que tiver concluído a tarefa. Você também precisa entregar as Instruções Táticas IX para concluir a missão.",
    [8771] = "Mate 30 Espreitareias da Colme'Ashi e fale novamente com o Comandante Mar'alith no Forte Cenariano, que fica em Silithus. Você também precisa entregar as Instruções de Combate II para concluir a missão.",
    [8772] = "Mate 30 Atalaias da Colme'Zora e fale novamente com o Comandante Mar'alith no Forte Cenariano, que fica em Silithus. Você também precisa entregar as Instruções de Combate VI para concluir a missão.",
